[{"id":"084bc61","elType":"container","isInner":false,"settings":{"_title":"Header","content_width":"full","css_classes":"te-block te-header","padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true},"flex_gap":{"unit":"px","size":0,"column":"0","row":"0","isLinked":true}},"elements":[{"id":"b923701","elType":"widget","widgetType":"html","isInner":false,"settings":{"_title":"Header — logo & menu","html":"<nav><div class="nav-inner"><a class="nav-logo" href="/"><svg class="nav-logo-icon" fill="none" viewbox="0 0 48 48" xmlns="http://www.w3.org/2000/svg"><rect fill="#1a6e62" height="10" rx="2" width="40" x="4" y="28"></rect><rect fill="#b8852a" height="8" rx="1" width="28" x="8" y="22"></rect><rect fill="#b8852a" height="10" rx="1" width="16" x="16" y="14"></rect><rect fill="rgba(255,255,255,0.7)" height="4" rx="1" width="4" x="10" y="24"></rect><rect fill="rgba(255,255,255,0.7)" height="4" rx="1" width="4" x="18" y="24"></rect><rect fill="rgba(255,255,255,0.7)" height="4" rx="1" width="4" x="26" y="24"></rect><circle cx="12" cy="38" fill="#0d2137" r="4"></circle><circle cx="12" cy="38" fill="#4a6080" r="2"></circle><circle cx="36" cy="38" fill="#0d2137" r="4"></circle><circle cx="36" cy="38" fill="#4a6080" r="2"></circle><line stroke="#1a6e62" stroke-width="1.5" x1="4" x2="44" y1="28" y2="28"></line></svg><div class="nav-logo-text"><span>Truman Enterprise</span><span>Narrowboat Trust</span></div></a><button aria-label="Menu" class="nav-hamburger"><span></span><span></span><span></span></button><ul class="nav-links"><li><a href="/">Home</a></li><li><a class="active" href="/our-trips/">Our Trips</a></li><li><a href="/get-involved/">Get Involved</a></li><li><a href="/support-us/">Support Us</a></li><li><a href="/contact/">Contact</a></li><li><a class="nav-cta" href="/book-a-trip/">Book a Trip</a></li></ul></div></nav>"},"elements":[]}]},{"id":"e32c983","elType":"container","isInner":false,"settings":{"_title":"Page banner","content_width":"full","css_classes":"te-block te-section","padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true},"flex_gap":{"unit":"px","size":0,"column":"0","row":"0","isLinked":true}},"elements":[{"id":"5531786","elType":"widget","widgetType":"text-editor","isInner":false,"settings":{"_title":"Page banner","editor":"<div class="page-hero" style="position:relative;min-height:520px;overflow:hidden;display:flex;align-items:flex-end;width:100%;"><img alt="Autherley canal junction" src="/wp-content/uploads/2026/10/truman-autherley-junction.jpg" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center 40%;display:block;"/><div class="page-hero-content"><h1>Our Trips</h1><p>Three beautiful routes along the Staffs &amp; Worcs Canal — April to October</p></div></div>"},"elements":[]}]},{"id":"ed9d23d","elType":"container","isInner":false,"settings":{"_title":"Choose Your Trip","content_width":"full","css_classes":"te-block te-section","padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true},"flex_gap":{"unit":"px","size":0,"column":"0","row":"0","isLinked":true}},"elements":[{"id":"4fac0e1","elType":"widget","widgetType":"text-editor","isInner":false,"settings":{"_title":"Choose Your Trip","editor":"<section><div class="section-inner"><div class="trips-page-layout"><!-- Left: Trip Details --><div><div class="section-label">Destinations</div><h2 class="section-title">Choose Your Trip</h2><p class="section-lead">We run trips to 3 destinations on the Staffs and Worcs Canal. All trips start and finish at Hatherton Marina, Queens Road, Calf Heath, Wolverhampton WV10 7DT. Trips run April to October, 7 days a week.</p><!-- Trip Cards --><div style="display:flex; flex-direction:column; gap:28px; margin-top:8px;"><!-- Coven --><div class="trip-card"><div class="trip-card-header" style="background: linear-gradient(135deg, #1b3a5c, #2c5f8a);"><div style="display:flex; justify-content:space-between; align-items:flex-start;"><div><h3>🍺 Coven Trip</h3><p style="color:rgba(255,255,255,0.8); font-family:sans-serif; font-size:0.88rem; margin-top:4px;">Most popular destination</p></div><div class="price">£110</div></div></div><div class="trip-card-body"><p>A 5 or 5½ hour round trip to the Anchor pub at Coven, including a 1–1½ hour stop for lunch.</p><div class="trip-detail"><span class="trip-detail-icon">⏱</span><strong>Duration:</strong> 5–5½ hours</div><div class="trip-detail"><span class="trip-detail-icon">👥</span><strong>Capacity:</strong> Up to 12 passengers</div><div class="trip-detail"><span class="trip-detail-icon">💷</span><strong>Cost:</strong> £110 for the whole boat</div><table class="lunch-options-table" style="margin-top:16px;"><thead><tr><th>Lunch Option</th><th>Timings</th><th>Stop</th></tr></thead><tbody><tr><td>Own food</td><td>10:30am – 3:30pm</td><td>1 hour</td></tr><tr><td>Fish &amp; chips (cash)</td><td>10:30am – 3:30pm</td><td>1 hour</td></tr><tr><td>Pub meal at the Anchor</td><td>10:30am – 4:00pm</td><td>2 hours</td></tr></tbody></table><div class="trip-note">ℹ️ Price does not include food. Fish &amp; chips not available on Sundays.</div><div style="margin-top:16px;"><a class="btn btn-primary" href="/book-a-trip/" style="padding:10px 20px; font-size:0.85rem;">Book This Trip</a></div></div></div><!-- Autherley --><div class="trip-card"><div class="trip-card-header" style="background: linear-gradient(135deg, #1a5c4e, #1a7a6e);"><div style="display:flex; justify-content:space-between; align-items:flex-start;"><div><h3>⚓ Autherley Trip</h3><p style="color:rgba(255,255,255,0.8); font-family:sans-serif; font-size:0.88rem; margin-top:4px;">Junction cruise</p></div><div class="price">£140</div></div></div><div class="trip-card-body"><p>A non-stop 6 hour round trip to Autherley Junction with the Shropshire Union Canal, including a stop to stretch your legs if time permits.</p><div class="trip-detail"><span class="trip-detail-icon">⏱</span><strong>Duration:</strong> 6 hours</div><div class="trip-detail"><span class="trip-detail-icon">👥</span><strong>Capacity:</strong> Up to 12 passengers</div><div class="trip-detail"><span class="trip-detail-icon">💷</span><strong>Cost:</strong> £140 for the whole boat</div><table class="lunch-options-table" style="margin-top:16px;"><thead><tr><th>Lunch Option</th><th>Timings</th><th>Stop</th></tr></thead><tbody><tr><td>Own food</td><td>10:30am – 4:30pm</td><td>20 mins</td></tr><tr><td>Fish &amp; chips (cash)</td><td>10:30am – 4:30pm</td><td>20 mins</td></tr></tbody></table><div class="trip-note">ℹ️ Price does not include food. Fish &amp; chips not available on Sundays.</div><div style="margin-top:16px;"><a class="btn btn-primary" href="/book-a-trip/" style="padding:10px 20px; font-size:0.85rem;">Book This Trip</a></div></div></div><!-- Penkridge --><div class="trip-card"><div class="trip-card-header" style="background: linear-gradient(135deg, #5c3a1a, #9a6228);"><div style="display:flex; justify-content:space-between; align-items:flex-start;"><div><h3>🔒 Penkridge Trip</h3><p style="color:rgba(255,255,255,0.8); font-family:sans-serif; font-size:0.88rem; margin-top:4px;">Adventure through 12 locks</p></div><div class="price">£170</div></div></div><div class="trip-card-body"><p>An 8-hour non-stop round trip to Penkridge, passing through 12 locks. Energetic passengers can experience mooring, steering and lock operation — or just sit back, relax and let the crew do all the work!</p><div class="trip-detail"><span class="trip-detail-icon">⏱</span><strong>Duration:</strong> 8 hours</div><div class="trip-detail"><span class="trip-detail-icon">🔒</span><strong>Locks:</strong> 12 locks</div><div class="trip-detail"><span class="trip-detail-icon">👥</span><strong>Capacity:</strong> Up to 12 passengers</div><div class="trip-detail"><span class="trip-detail-icon">💷</span><strong>Cost:</strong> £170 for the whole boat</div><table class="lunch-options-table" style="margin-top:16px;"><thead><tr><th>Lunch Option</th><th>Timings</th><th>Stop</th></tr></thead><tbody><tr><td>Own food</td><td>9:30am – 5:30pm</td><td>Non-stop</td></tr><tr><td>Take-away (Cross Keys pub)</td><td>9:30am – 5:30pm</td><td>Non-stop</td></tr></tbody></table><div class="trip-note">ℹ️ Price does not include food.</div><div style="margin-top:16px;"><a class="btn btn-primary" href="/book-a-trip/" style="padding:10px 20px; font-size:0.85rem;">Book This Trip</a></div></div></div></div><!-- Accordion: Our Boat, Safety --><div style="margin-top:48px;"><div class="section-label">More Information</div><h2 class="section-title">What to Expect</h2><div class="accordion"><div class="accordion-item"><button class="accordion-header">🚢 Our Boat — Narrowboat Enterprise <span class="accordion-icon">+</span></button><div class="accordion-body"><p>Narrowboat Enterprise is a 70ft canal boat designed especially for carrying passengers with mobility issues. It has:</p><ul><li>Ramps &amp; hydraulic passenger lift</li><li>Seating for up to 12 passengers (minimum 2 leaders/staff required)</li><li>Large open front deck</li><li>Small kitchen with fridge &amp; 2 gas burners</li><li>Large open cabin with deep picture windows</li><li>Central heating</li><li>Accessible toilet</li><li>Free hot &amp; cold drinks for all passengers</li><li>Qualified skipper and crew member on every trip</li><li>Free secure parking at the Marina</li></ul></div></div><div class="accordion-item"><button class="accordion-header">🛡️ Safety &amp; Crew Competency <span class="accordion-icon">+</span></button><div class="accordion-body"><h4>Crew Competency</h4><p>Each trip has a skipper and crew member who have passed the appropriate course accredited by the National Community Boats Association (NCBA). All Trust skippers hold the Certificate in Community Boat Management (CCBM). Crew members hold a Community Crew Course (CCC) certificate. All crew undertake update training annually.</p><h4>DBS Checks</h4><p>The designated skipper and crew on every trip are required to undergo an enhanced DBS check.</p><h4>Risk Assessments</h4><p>The Trust undertakes risk assessments which are regularly reviewed. Risk assessments are available on request.</p><h4>Insurance</h4><p>The Trust carries Public and Employer Liability Insurance of £10,000,000 in each instance. Our current insurance certificate is on display on board the Enterprise.</p></div></div><div class="accordion-item"><button class="accordion-header">💳 How to Pay <span class="accordion-icon">+</span></button><div class="accordion-body"><p>Payment may be made by <strong>cheque</strong> or by <strong>BACS</strong> — details will be shown on your invoice.</p><p>For BACS payments, please refer to your invoice for our bank details and quote your invoice number or trip date to ensure your payment is allocated correctly.</p><p><strong>Payment is due 28 days before each trip.</strong> Receipts are available on request.</p><p style="margin-top:12px;">For any queries about payments, contact Chris Rogers:<br/> 📞 <a href="tel:07763214524" style="color:var(--teal);">07763 214524</a><br/> ✉️ <a href="mailto:treasurer@truman-enterprise.org.uk" style="color:var(--teal);">treasurer@truman-enterprise.org.uk</a></p></div></div></div></div></div><!-- Right: Calendar + How to Book --><div class="booking-side-panel"><div class="section-label">Availability</div><h3 style="color:var(--navy); font-size:1.2rem; margin-bottom:16px;">Trip Diary</h3><p style="font-family:sans-serif; font-size:0.85rem; color:var(--text-light); margin-bottom:20px;">Check dates below, then complete the booking form. Green dates are available — click to start your booking.</p><div class="calendar-wrapper" id="booking-calendar"><div class="calendar-header"><button class="cal-nav-btn cal-prev">‹</button><h3 class="cal-month-label">Loading...</h3><button class="cal-nav-btn cal-next">›</button></div><div class="calendar-grid"><div class="calendar-weekdays"><div>Mo</div><div>Tu</div><div>We</div><div>Th</div><div>Fr</div><div>Sa</div><div>Su</div></div><div class="calendar-days"></div></div><div class="calendar-legend"><div class="legend-item"><div class="legend-dot available"></div> Available</div><div class="legend-item"><div class="legend-dot provisional"></div> Provisional</div><div class="legend-item"><div class="legend-dot booked"></div> Booked</div></div></div><div id="booking-section" style="margin-top:28px;"><div style="background:white; border-radius:10px; padding:24px; box-shadow:var(--shadow);"><h4 style="color:var(--navy); margin-bottom:16px; font-size:1rem;">How to Book</h4><div class="how-to-book-steps"><div class="step"><div class="step-num">1</div><div class="step-text">Check the <strong>calendar</strong> above for your preferred date</div></div><div class="step"><div class="step-num">2</div><div class="step-text">Complete the <strong><a href="/book-a-trip/" style="color:var(--teal);">online booking form</a></strong></div></div><div class="step"><div class="step-num">3</div><div class="step-text">Read and agree to the <strong>Terms &amp; Conditions</strong></div></div><div class="step"><div class="step-num">4</div><div class="step-text">Your trip will be <strong>confirmed by e-mail</strong> with an invoice</div></div></div><hr class="divider" style="margin:16px 0;"/><p style="font-family:sans-serif; font-size:0.82rem; color:var(--text-light); margin-bottom:8px;"><strong style="color:var(--navy);">Phone:</strong></p><p style="font-family:sans-serif; font-size:1rem; color:var(--navy); font-weight:bold; margin-bottom:8px;"><a href="tel:07895053090" style="color:var(--navy); text-decoration:none;">07895 053090</a></p><p style="font-family:sans-serif; font-size:0.82rem; color:var(--text-light); margin-bottom:4px;"><strong style="color:var(--navy);">Email:</strong></p><p style="font-family:sans-serif; font-size:0.8rem;"><a href="mailto:enterprise@truman-enterprise.org.uk" style="color:var(--teal);">enterprise@truman-enterprise.org.uk</a></p><div style="margin-top:16px;"><a class="btn btn-primary" href="/book-a-trip/" style="width:100%; text-align:center; display:block; padding:12px;">Book Online</a></div></div><!-- Location --><div style="background:white; border-radius:10px; padding:24px; box-shadow:var(--shadow); margin-top:20px;"><h4 style="color:var(--navy); margin-bottom:12px; font-size:1rem;">📍 Where We Are</h4><p style="font-family:sans-serif; font-size:0.85rem; color:var(--text-light); line-height:1.6;"> Hatherton Marina<br/>Queens Road, Calf Heath<br/>Wolverhampton<br/><strong style="color:var(--navy);">WV10 7DT</strong></p><div class="what3words" style="margin-top:10px; display:inline-flex;"> /// clarifies.overhead.paths </div><div class="location-map-placeholder"><div style="font-size:2rem;">🗺️</div><div><strong>Hatherton Marina</strong><br/><small>WV10 7DT</small></div><a class="btn btn-primary" href="https://maps.google.com/?q=Hatherton+Marina+Queens+Road+Calf+Heath+Wolverhampton+WV10+7DT" style="padding:8px 16px; font-size:0.8rem; margin-top:8px;" target="_blank">Open in Google Maps</a></div></div></div></div></div></div></section>"},"elements":[]}]},{"id":"81a052e","elType":"container","isInner":false,"settings":{"_title":"Footer","content_width":"full","css_classes":"te-block te-footer","padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true},"flex_gap":{"unit":"px","size":0,"column":"0","row":"0","isLinked":true}},"elements":[{"id":"0bdee52","elType":"widget","widgetType":"html","isInner":false,"settings":{"_title":"Footer + site scripts","html":"<footer><div class="footer-inner"><div class="footer-cta-strip"><div class="footer-cta-strip-text"><h3>Truman Enterprise Narrowboat Trust</h3><p>Making waterways accessible to everyone since 1968 — Registered Charity No. 1037914</p></div></div><div class="footer-grid"><div class="footer-brand"><p>A volunteer-run charity providing accessible canal boat day trips for elderly, disabled and community groups across the West Midlands since 1968.</p><span class="footer-charity-no">Registered Charity No. 1037914</span></div><div class="footer-col"><h4>Navigate</h4><ul><li><a href="/">Home</a></li><li><a href="/our-trips/">Our Trips</a></li><li><a href="/book-a-trip/">Book a Trip</a></li><li><a href="/get-involved/">Get Involved</a></li><li><a href="/support-us/">Support Us</a></li><li><a href="/contact/">Contact</a></li></ul></div><div class="footer-col"><h4>Contact Us</h4><a href="tel:07895053090">07895 053090</a><a href="mailto:enterprise@truman-enterprise.org.uk">enterprise@truman-enterprise.org.uk</a><p class="footer-address" style="margin-top:14px;">Hatherton Marina<br/>Queens Road, Calf Heath<br/>Wolverhampton WV10 7DT</p></div><div class="footer-col"><h4>Season</h4><p>Trips run <strong style="color:rgba(255,255,255,0.7);">April to October</strong>, 7 days a week, from Hatherton Marina.</p><p style="margin-top:16px;"><span class="ncba-badge">🚢 NCBA Member</span></p></div></div><div class="footer-bottom"><p>© 2025 Truman Enterprise Narrowboat Trust. Registered Charity No. 1037914.</p><p>Member of the National Community Boats Association</p></div></div></footer>
<script>
// =============================================
// Truman Enterprise Narrowboat Trust - JS
// =============================================

// ---- Navigation hamburger ----
(function (init) { if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init(); })(function () {
  const hamburger = document.querySelector('.nav-hamburger');
  const navLinks = document.querySelector('.nav-links');
  if (hamburger && navLinks) {
    hamburger.addEventListener('click', function () {
      navLinks.classList.toggle('open');
    });
    document.addEventListener('click', function (e) {
      if (!e.target.closest('nav')) navLinks.classList.remove('open');
    });
  }


  // Init all components
  initHeroSlider();
  initAccordions();
  initCalendar();
  initBookingForm();
  animateStats();
});

// ---- Hero Slider ----
function initHeroSlider() {
  const slides = document.querySelectorAll('.hero-slide');
  const dots = document.querySelectorAll('.hero-dot');
  if (!slides.length) return;

  let current = 0;
  let timer = null;

  function goTo(idx) {
    slides[current].classList.remove('active');
    if (dots[current]) dots[current].classList.remove('active');
    current = (idx + slides.length) % slides.length;
    slides[current].classList.add('active');
    if (dots[current]) dots[current].classList.add('active');
  }

  function start() { timer = setInterval(() => goTo(current + 1), 5000); }
  function reset() { clearInterval(timer); start(); }

  dots.forEach((dot, i) => dot.addEventListener('click', () => { goTo(i); reset(); }));

  slides[0].classList.add('active');
  if (dots[0]) dots[0].classList.add('active');
  if (slides.length > 1) start();
}

// ---- Accordions ----
function initAccordions() {
  document.querySelectorAll('.accordion-header').forEach(header => {
    header.addEventListener('click', function () {
      const body = this.nextElementSibling;
      const isOpen = this.classList.contains('open');

      // Close all in this accordion group
      const accordion = this.closest('.accordion');
      if (accordion) {
        accordion.querySelectorAll('.accordion-header').forEach(h => {
          h.classList.remove('open');
          h.nextElementSibling.classList.remove('open');
        });
      }

      if (!isOpen) {
        this.classList.add('open');
        body.classList.add('open');
      }
    });
  });
}

// ---- Calendar ----
const TRIP_DATA = {
  // Format: 'YYYY-MM-DD': 'available' | 'provisional' | 'booked'
  // These are example dates - in production these would come from a backend
};

// Generate sample data for April-October of current year
(function seedCalendar() {
  const year = new Date().getFullYear();
  const months = [3, 4, 5, 6, 7, 8, 9]; // Apr-Oct (0-indexed)
  const statuses = ['available', 'available', 'available', 'provisional', 'booked'];
  months.forEach(m => {
    const daysInMonth = new Date(year, m + 1, 0).getDate();
    for (let d = 1; d <= daysInMonth; d++) {
      if ([0, 6].includes(new Date(year, m, d).getDay())) continue; // skip some
      if (Math.random() > 0.45) {
        const key = `${year}-${String(m + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        TRIP_DATA[key] = statuses[Math.floor(Math.random() * statuses.length)];
      }
    }
  });
})();

function initCalendar() {
  const wrapper = document.getElementById('booking-calendar');
  if (!wrapper) return;

  const today = new Date();
  let viewYear = today.getFullYear();
  let viewMonth = today.getMonth(); // Start at current month

  // Start at April if current month is before April
  if (viewMonth < 3) viewMonth = 3;

  renderCalendar(wrapper, viewYear, viewMonth);

  wrapper.querySelector('.cal-prev').addEventListener('click', () => {
    viewMonth--;
    if (viewMonth < 0) { viewMonth = 11; viewYear--; }
    renderCalendar(wrapper, viewYear, viewMonth);
  });

  wrapper.querySelector('.cal-next').addEventListener('click', () => {
    viewMonth++;
    if (viewMonth > 11) { viewMonth = 0; viewYear++; }
    renderCalendar(wrapper, viewYear, viewMonth);
  });
}

function renderCalendar(wrapper, year, month) {
  const monthNames = ['January','February','March','April','May','June',
                      'July','August','September','October','November','December'];
  const today = new Date();

  wrapper.querySelector('.cal-month-label').textContent = `${monthNames[month]} ${year}`;

  const daysContainer = wrapper.querySelector('.calendar-days');
  daysContainer.innerHTML = '';

  const firstDay = new Date(year, month, 1).getDay();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const prevDays = new Date(year, month, 0).getDate();

  // Monday-first offset
  const offset = (firstDay + 6) % 7;

  // Prev month padding
  for (let i = offset - 1; i >= 0; i--) {
    const btn = document.createElement('button');
    btn.className = 'cal-day other-month';
    btn.textContent = prevDays - i;
    daysContainer.appendChild(btn);
  }

  // Current month days
  for (let d = 1; d <= daysInMonth; d++) {
    const dateKey = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
    const status = TRIP_DATA[dateKey];
    const btn = document.createElement('button');
    btn.className = 'cal-day';
    btn.textContent = d;

    if (status) btn.classList.add(status);

    const isToday = d === today.getDate() && month === today.getMonth() && year === today.getFullYear();
    if (isToday) btn.classList.add('today');

    if (status === 'available') {
      btn.title = 'Available - click to book';
      btn.addEventListener('click', () => {
        const bookingSection = document.getElementById('booking-section');
        if (bookingSection) {
          bookingSection.scrollIntoView({ behavior: 'smooth' });
          // Pre-fill date if form exists
          const dateInput = document.querySelector('input[name="trip1_date"]');
          if (dateInput) {
            dateInput.value = dateKey;
          }
        }
      });
    } else if (status === 'booked') {
      btn.title = 'Fully booked';
    } else if (status === 'provisional') {
      btn.title = 'Provisional booking - contact us to enquire';
    }

    daysContainer.appendChild(btn);
  }

  // Next month padding
  const total = offset + daysInMonth;
  const remaining = total % 7 === 0 ? 0 : 7 - (total % 7);
  for (let d = 1; d <= remaining; d++) {
    const btn = document.createElement('button');
    btn.className = 'cal-day other-month';
    btn.textContent = d;
    daysContainer.appendChild(btn);
  }
}

// ---- Booking Form ----
function initBookingForm() {
  const form = document.getElementById('booking-form');
  if (!form) return;

  form.addEventListener('submit', function (e) {
    e.preventDefault();

    const terms = form.querySelector('input[name="terms"]');
    if (!terms || !terms.checked) {
      alert('Please read and agree to the Terms and Conditions before submitting.');
      return;
    }

    // Collect form data
    const data = new FormData(form);
    const subject = `Boat Trip Booking - ${data.get('group_name') || 'New Booking'}`;
    const body = buildEmailBody(data);

    // Open mailto link
    const mailto = `mailto:enterprise@truman-enterprise.org.uk?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
    window.location.href = mailto;

    const success = form.querySelector('.success-message');
    if (success) success.style.display = 'block';
  });
}

function buildEmailBody(data) {
  let body = 'TRIP BOOKING REQUEST\n';
  body += '====================\n\n';
  body += `Group Name: ${data.get('group_name') || ''}\n`;
  body += `Contact Name: ${data.get('contact_name') || ''}\n`;
  body += `Address: ${data.get('address') || ''}\n`;
  body += `Phone: ${data.get('phone') || ''}\n`;
  body += `Email: ${data.get('email') || ''}\n`;
  body += `Day-of Contact: ${data.get('day_contact') || ''}\n`;
  body += `Day-of Mobile: ${data.get('day_mobile') || ''}\n\n`;
  body += 'TRIPS REQUESTED:\n';
  for (let i = 1; i <= 3; i++) {
    const date = data.get(`trip${i}_date`);
    const dest = data.get(`trip${i}_dest`);
    const lunch = data.get(`trip${i}_lunch`);
    if (date || dest) {
      body += `  Trip ${i}: Date: ${date || '—'} | Destination: ${dest || '—'} | Lunch: ${lunch || '—'}\n`;
    }
  }
  body += `\nPhotos consent: ${data.get('photos') ? 'Yes' : 'No'}\n`;
  return body;
}

// ---- Stats counter animation ----
function animateStats() {
  const stats = document.querySelectorAll('.stat-number[data-target]');
  if (!stats.length) return;

  const observer = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        const el = entry.target;
        const target = parseInt(el.dataset.target);
        const suffix = el.dataset.suffix || '';
        let current = 0;
        const step = Math.ceil(target / 50);
        const interval = setInterval(() => {
          current = Math.min(current + step, target);
          el.textContent = current.toLocaleString() + suffix;
          if (current >= target) clearInterval(interval);
        }, 30);
        observer.unobserve(el);
      }
    });
  }, { threshold: 0.5 });

  stats.forEach(stat => observer.observe(stat));
}

</script>"},"elements":[]}]}]

