ll","css_classes":"te-block te-section","padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true},"flex_gap":{"unit":"px","size":0,"column":"0","row":"0","isLinked":true}},"elements":[{"id":"4b376da","elType":"widget","widgetType":"text-editor","isInner":false,"settings":{"_title":"Page banner","editor":"<div class="page-hero" style="position:relative;min-height:520px;overflow:hidden;display:flex;align-items:flex-end;width:100%;"><img alt="Volunteers on the narrowboat" src="/wp-content/uploads/2026/10/truman-volunteers-boat.jpg" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center 40%;display:block;"/><div class="page-hero-content"><h1>Get Involved</h1><p>Join our team of dedicated volunteers and make a real difference</p></div></div>"},"elements":[]}]},{"id":"a3cdda8","elType":"container","isInner":false,"settings":{"_title":"Be Part of Something Special","content_width":"full","css_classes":"te-block te-section","padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true},"flex_gap":{"unit":"px","size":0,"column":"0","row":"0","isLinked":true}},"elements":[{"id":"0aa1e84","elType":"widget","widgetType":"text-editor","isInner":false,"settings":{"_title":"Be Part of Something Special","editor":"<section><div class="section-inner"><div class="section-label">Volunteering</div><h2 class="section-title">Be Part of Something Special</h2><p class="section-lead">Our trust is dedicated to providing memorable canal boat experiences for elderly and disabled members of our community. Every trip we offer brings joy, connection, and a sense of freedom to those who might otherwise miss out. We can only continue this vital work with your support.</p><div class="roles-grid"><div class="role-card"><div class="role-icon">⚓</div><h3>Volunteer as a Crew Member</h3><p>Love being on the water? Like meeting new people? Under the supervision of an experienced skipper, our crew members are essential to every trip. Help with lock operations, interact with passengers, and ensure everyone has a safe and enjoyable experience. No previous experience necessary — just enthusiasm and a caring nature. Full training provided.</p></div><div class="role-card"><div class="role-icon">🚢</div><h3>Train to be a Skipper</h3><p>Experienced boat crew can volunteer to be trained as a skipper — the person in charge of each trip. Good boat handling skills needed and full training provided by our NCBA qualified trainer. You'll gain valuable skills while making a real difference to people's lives.</p></div><div class="role-card"><div class="role-icon">📋</div><h3>Administrative Support</h3><p>Behind every boat trip is careful planning and coordination. We need volunteers to help with booking systems, maintaining passenger records, scheduling trips, coordinating volunteers, and general office administration.</p></div><div class="role-card"><div class="role-icon">📣</div><h3>Marketing &amp; Communications</h3><p>Help us spread the word! We're looking for volunteers to manage social media, create promotional materials, write newsletters, take photos during trips, maintain our website, and help with community outreach. Your skills could help us reach more people who would benefit from our services.</p></div><div class="role-card"><div class="role-icon">🎪</div><h3>Fundraising &amp; Events</h3><p>Support our financial sustainability by helping organise fundraising events, writing grant applications, managing donor relationships, or coordinating charity activities. Every pound raised keeps our boat running and our community thriving.</p></div><div class="role-card"><div class="role-icon">🔧</div><h3>Maintenance &amp; Technical</h3><p>Do you have practical skills? We need help with boat maintenance, equipment checks (especially cleaning and painting), ensuring our disabled lift operates safely, general repairs, and keeping our marina facilities in good condition. Your expertise keeps us safe and operational.</p></div><div class="role-card"><div class="role-icon">🏛️</div><h3>Trustee &amp; Governance</h3><p>Join our board of trustees and help shape the future of our organisation. We welcome people with skills in finance, legal matters, charity governance, or strategic planning. Usually requires attendance at quarterly meetings.</p></div><div class="role-card" style="border-left-color: var(--gold);"><div class="role-icon">💛</div><h3>Donating Your Time</h3><p>Whatever your skills, interests or available time, there's a way you can help. Whether you can spare a few hours a month or want to make a regular commitment, every contribution matters. You'll join a friendly team of dedicated volunteers who share a passion for making our waterways accessible to all.</p></div></div></div></section>"},"elements":[]}]},{"id":"f2b38f1","elType":"container","isInner":false,"settings":{"_title":"Why Volunteer With Us?","content_width":"full","css_classes":"te-block te-section","padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true},"flex_gap":{"unit":"px","size":0,"column":"0","row":"0","isLinked":true}},"elements":[{"id":"0384601","elType":"widget","widgetType":"text-editor","isInner":false,"settings":{"_title":"Why Volunteer With Us?","editor":"<section class="bg-cream"><div class="section-inner"><div style="display:grid; grid-template-columns:1fr 1fr; gap:48px; align-items:center;"><div><img alt="Volunteers and passengers on the canal boat" src="/wp-content/uploads/2026/10/truman-volunteers-canal.jpg" style="width:100%; border-radius:12px; box-shadow:var(--shadow);"/></div><div><div class="section-label">Benefits</div><h2 class="section-title">Why Volunteer With Us?</h2><div style="display:flex; flex-direction:column; gap:14px; margin-top:8px;"><div style="display:flex; gap:14px; align-items:flex-start;"><span style="color:var(--teal); font-size:1.2rem; flex-shrink:0;">✓</span><div style="font-family:sans-serif; font-size:0.92rem; color:var(--text-light);"><strong style="color:var(--navy);">Meet like-minded people</strong> — join a warm, welcoming team</div></div><div style="display:flex; gap:14px; align-items:flex-start;"><span style="color:var(--teal); font-size:1.2rem; flex-shrink:0;">✓</span><div style="font-family:sans-serif; font-size:0.92rem; color:var(--text-light);"><strong style="color:var(--navy);">Learn new skills</strong> — from boat handling to marketing</div></div><div style="display:flex; gap:14px; align-items:flex-start;"><span style="color:var(--teal); font-size:1.2rem; flex-shrink:0;">✓</span><div style="font-family:sans-serif; font-size:0.92rem; color:var(--text-light);"><strong style="color:var(--navy);">Gain boating experience</strong> — including NCBA accredited training</div></div><div style="display:flex; gap:14px; align-items:flex-start;"><span style="color:var(--teal); font-size:1.2rem; flex-shrink:0;">✓</span><div style="font-family:sans-serif; font-size:0.92rem; color:var(--text-light);"><strong style="color:var(--navy);">Make a genuine difference</strong> — to your local community</div></div><div style="display:flex; gap:14px; align-items:flex-start;"><span style="color:var(--teal); font-size:1.2rem; flex-shrink:0;">✓</span><div style="font-family:sans-serif; font-size:0.92rem; color:var(--text-light);"><strong style="color:var(--navy);">Enjoy time on beautiful canals</strong> — in the West Midlands countryside</div></div><div style="display:flex; gap:14px; align-items:flex-start;"><span style="color:var(--teal); font-size:1.2rem; flex-shrink:0;">✓</span><div style="font-family:sans-serif; font-size:0.92rem; color:var(--text-light);"><strong style="color:var(--navy);">Full training and support</strong> — provided in your role</div></div></div></div></div></div></section>"},"elements":[]}]},{"id":"81fc226","elType":"container","isInner":false,"settings":{"_title":"Ready to Get Involved?","content_width":"full","css_classes":"te-block te-section","padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true},"flex_gap":{"unit":"px","size":0,"column":"0","row":"0","isLinked":true}},"elements":[{"id":"c3d3342","elType":"widget","widgetType":"text-editor","isInner":false,"settings":{"_title":"Ready to Get Involved?","editor":"<section style="background: linear-gradient(135deg, var(--navy) 0%, #2c5f8a 100%); text-align:center;"><div class="section-inner"><h2 style="color:white; font-size:2rem; margin-bottom:16px;">Ready to Get Involved?</h2><p style="font-family:sans-serif; font-size:1.05rem; color:rgba(255,255,255,0.85); max-width:600px; margin:0 auto 32px; line-height:1.7;"> Contact us today to discuss how you can support our trust. No commitment necessary — just get in touch for an informal chat about the opportunities available. </p><div style="display:flex; gap:16px; justify-content:center; flex-wrap:wrap;"><a class="btn btn-gold" href="tel:07895053090">📞 Call Jenny: 07895 053090</a><a class="btn btn-outline" href="mailto:volunteer@truman-enterprise.org.uk" style="border-color:white; color:white;">✉️ volunteer@truman-enterprise.org.uk</a></div></div></section>"},"elements":[]}]},{"id":"4e429ec","elType":"container","isInner":false,"settings":{"_title":"Footer","content_width":"full","css_classes":"te-block te-footer","padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true},"flex_gap":{"unit":"px","size":0,"column":"0","row":"0","isLinked":true}},"elements":[{"id":"c84d2ce","elType":"widget","widgetType":"html","isInner":false,"settings":{"_title":"Footer + site scripts","html":"<footer><div class="footer-inner"><div class="footer-cta-strip"><div class="footer-cta-strip-text"><h3>Truman Enterprise Narrowboat Trust</h3><p>Making waterways accessible to everyone since 1968 — Registered Charity No. 1037914</p></div></div><div class="footer-grid"><div class="footer-brand"><p>A volunteer-run charity providing accessible canal boat day trips for elderly, disabled and community groups across the West Midlands since 1968.</p><span class="footer-charity-no">Registered Charity No. 1037914</span></div><div class="footer-col"><h4>Navigate</h4><ul><li><a href="/">Home</a></li><li><a href="/our-trips/">Our Trips</a></li><li><a href="/book-a-trip/">Book a Trip</a></li><li><a href="/get-involved/">Get Involved</a></li><li><a href="/support-us/">Support Us</a></li><li><a href="/contact/">Contact</a></li></ul></div><div class="footer-col"><h4>Contact Us</h4><a href="tel:07895053090">07895 053090</a><a href="mailto:enterprise@truman-enterprise.org.uk">enterprise@truman-enterprise.org.uk</a><p class="footer-address" style="margin-top:14px;">Hatherton Marina<br/>Queens Road, Calf Heath<br/>Wolverhampton WV10 7DT</p></div><div class="footer-col"><h4>Season</h4><p>Trips run <strong style="color:rgba(255,255,255,0.7);">April to October</strong>, 7 days a week, from Hatherton Marina.</p><p style="margin-top:16px;"><span class="ncba-badge">🚢 NCBA Member</span></p></div></div><div class="footer-bottom"><p>© 2025 Truman Enterprise Narrowboat Trust. Registered Charity No. 1037914.</p><p>Member of the National Community Boats Association</p></div></div></footer>
<script>
// =============================================
// Truman Enterprise Narrowboat Trust - JS
// =============================================

// ---- Navigation hamburger ----
(function (init) { if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init(); })(function () {
  const hamburger = document.querySelector('.nav-hamburger');
  const navLinks = document.querySelector('.nav-links');
  if (hamburger && navLinks) {
    hamburger.addEventListener('click', function () {
      navLinks.classList.toggle('open');
    });
    document.addEventListener('click', function (e) {
      if (!e.target.closest('nav')) navLinks.classList.remove('open');
    });
  }


  // Init all components
  initHeroSlider();
  initAccordions();
  initCalendar();
  initBookingForm();
  animateStats();
});

// ---- Hero Slider ----
function initHeroSlider() {
  const slides = document.querySelectorAll('.hero-slide');
  const dots = document.querySelectorAll('.hero-dot');
  if (!slides.length) return;

  let current = 0;
  let timer = null;

  function goTo(idx) {
    slides[current].classList.remove('active');
    if (dots[current]) dots[current].classList.remove('active');
    current = (idx + slides.length) % slides.length;
    slides[current].classList.add('active');
    if (dots[current]) dots[current].classList.add('active');
  }

  function start() { timer = setInterval(() => goTo(current + 1), 5000); }
  function reset() { clearInterval(timer); start(); }

  dots.forEach((dot, i) => dot.addEventListener('click', () => { goTo(i); reset(); }));

  slides[0].classList.add('active');
  if (dots[0]) dots[0].classList.add('active');
  if (slides.length > 1) start();
}

// ---- Accordions ----
function initAccordions() {
  document.querySelectorAll('.accordion-header').forEach(header => {
    header.addEventListener('click', function () {
      const body = this.nextElementSibling;
      const isOpen = this.classList.contains('open');

      // Close all in this accordion group
      const accordion = this.closest('.accordion');
      if (accordion) {
        accordion.querySelectorAll('.accordion-header').forEach(h => {
          h.classList.remove('open');
          h.nextElementSibling.classList.remove('open');
        });
      }

      if (!isOpen) {
        this.classList.add('open');
        body.classList.add('open');
      }
    });
  });
}

// ---- Calendar ----
const TRIP_DATA = {
  // Format: 'YYYY-MM-DD': 'available' | 'provisional' | 'booked'
  // These are example dates - in production these would come from a backend
};

// Generate sample data for April-October of current year
(function seedCalendar() {
  const year = new Date().getFullYear();
  const months = [3, 4, 5, 6, 7, 8, 9]; // Apr-Oct (0-indexed)
  const statuses = ['available', 'available', 'available', 'provisional', 'booked'];
  months.forEach(m => {
    const daysInMonth = new Date(year, m + 1, 0).getDate();
    for (let d = 1; d <= daysInMonth; d++) {
      if ([0, 6].includes(new Date(year, m, d).getDay())) continue; // skip some
      if (Math.random() > 0.45) {
        const key = `${year}-${String(m + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        TRIP_DATA[key] = statuses[Math.floor(Math.random() * statuses.length)];
      }
    }
  });
})();

function initCalendar() {
  const wrapper = document.getElementById('booking-calendar');
  if (!wrapper) return;

  const today = new Date();
  let viewYear = today.getFullYear();
  let viewMonth = today.getMonth(); // Start at current month

  // Start at April if current month is before April
  if (viewMonth < 3) viewMonth = 3;

  renderCalendar(wrapper, viewYear, viewMonth);

  wrapper.querySelector('.cal-prev').addEventListener('click', () => {
    viewMonth--;
    if (viewMonth < 0) { viewMonth = 11; viewYear--; }
    renderCalendar(wrapper, viewYear, viewMonth);
  });

  wrapper.querySelector('.cal-next').addEventListener('click', () => {
    viewMonth++;
    if (viewMonth > 11) { viewMonth = 0; viewYear++; }
    renderCalendar(wrapper, viewYear, viewMonth);
  });
}

function renderCalendar(wrapper, year, month) {
  const monthNames = ['January','February','March','April','May','June',
                      'July','August','September','October','November','December'];
  const today = new Date();

  wrapper.querySelector('.cal-month-label').textContent = `${monthNames[month]} ${year}`;

  const daysContainer = wrapper.querySelector('.calendar-days');
  daysContainer.innerHTML = '';

  const firstDay = new Date(year, month, 1).getDay();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const prevDays = new Date(year, month, 0).getDate();

  // Monday-first offset
  const offset = (firstDay + 6) % 7;

  // Prev month padding
  for (let i = offset - 1; i >= 0; i--) {
    const btn = document.createElement('button');
    btn.className = 'cal-day other-month';
    btn.textContent = prevDays - i;
    daysContainer.appendChild(btn);
  }

  // Current month days
  for (let d = 1; d <= daysInMonth; d++) {
    const dateKey = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
    const status = TRIP_DATA[dateKey];
    const btn = document.createElement('button');
    btn.className = 'cal-day';
    btn.textContent = d;

    if (status) btn.classList.add(status);

    const isToday = d === today.getDate() && month === today.getMonth() && year === today.getFullYear();
    if (isToday) btn.classList.add('today');

    if (status === 'available') {
      btn.title = 'Available - click to book';
      btn.addEventListener('click', () => {
        const bookingSection = document.getElementById('booking-section');
        if (bookingSection) {
          bookingSection.scrollIntoView({ behavior: 'smooth' });
          // Pre-fill date if form exists
          const dateInput = document.querySelector('input[name="trip1_date"]');
          if (dateInput) {
            dateInput.value = dateKey;
          }
        }
      });
    } else if (status === 'booked') {
      btn.title = 'Fully booked';
    } else if (status === 'provisional') {
      btn.title = 'Provisional booking - contact us to enquire';
    }

    daysContainer.appendChild(btn);
  }

  // Next month padding
  const total = offset + daysInMonth;
  const remaining = total % 7 === 0 ? 0 : 7 - (total % 7);
  for (let d = 1; d <= remaining; d++) {
    const btn = document.createElement('button');
    btn.className = 'cal-day other-month';
    btn.textContent = d;
    daysContainer.appendChild(btn);
  }
}

// ---- Booking Form ----
function initBookingForm() {
  const form = document.getElementById('booking-form');
  if (!form) return;

  form.addEventListener('submit', function (e) {
    e.preventDefault();

    const terms = form.querySelector('input[name="terms"]');
    if (!terms || !terms.checked) {
      alert('Please read and agree to the Terms and Conditions before submitting.');
      return;
    }

    // Collect form data
    const data = new FormData(form);
    const subject = `Boat Trip Booking - ${data.get('group_name') || 'New Booking'}`;
    const body = buildEmailBody(data);

    // Open mailto link
    const mailto = `mailto:enterprise@truman-enterprise.org.uk?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
    window.location.href = mailto;

    const success = form.querySelector('.success-message');
    if (success) success.style.display = 'block';
  });
}

function buildEmailBody(data) {
  let body = 'TRIP BOOKING REQUEST\n';
  body += '====================\n\n';
  body += `Group Name: ${data.get('group_name') || ''}\n`;
  body += `Contact Name: ${data.get('contact_name') || ''}\n`;
  body += `Address: ${data.get('address') || ''}\n`;
  body += `Phone: ${data.get('phone') || ''}\n`;
  body += `Email: ${data.get('email') || ''}\n`;
  body += `Day-of Contact: ${data.get('day_contact') || ''}\n`;
  body += `Day-of Mobile: ${data.get('day_mobile') || ''}\n\n`;
  body += 'TRIPS REQUESTED:\n';
  for (let i = 1; i <= 3; i++) {
    const date = data.get(`trip${i}_date`);
    const dest = data.get(`trip${i}_dest`);
    const lunch = data.get(`trip${i}_lunch`);
    if (date || dest) {
      body += `  Trip ${i}: Date: ${date || '—'} | Destination: ${dest || '—'} | Lunch: ${lunch || '—'}\n`;
    }
  }
  body += `\nPhotos consent: ${data.get('photos') ? 'Yes' : 'No'}\n`;
  return body;
}

// ---- Stats counter animation ----
function animateStats() {
  const stats = document.querySelectorAll('.stat-number[data-target]');
  if (!stats.length) return;

  const observer = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        const el = entry.target;
        const target = parseInt(el.dataset.target);
        const suffix = el.dataset.suffix || '';
        let current = 0;
        const step = Math.ceil(target / 50);
        const interval = setInterval(() => {
          current = Math.min(current + step, target);
          el.textContent = current.toLocaleString() + suffix;
          if (current >= target) clearInterval(interval);
        }, 30);
        observer.unobserve(el);
      }
    });
  }, { threshold: 0.5 });

  stats.forEach(stat => observer.observe(stat));
}

</script>"},"elements":[]}]}]

