ll","css_classes":"te-block te-section","padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true},"flex_gap":{"unit":"px","size":0,"column":"0","row":"0","isLinked":true}},"elements":[{"id":"93b01c1","elType":"widget","widgetType":"text-editor","isInner":false,"settings":{"_title":"Page banner","editor":"<div class="page-hero" style="position:relative;min-height:520px;overflow:hidden;display:flex;align-items:flex-end;width:100%;"><img alt="Kingfisher on the canal" src="/wp-content/uploads/2026/10/truman-boat-kingfisher.jpg" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center 40%;display:block;"/><div class="page-hero-content"><h1>Support Our Trust</h1><p>Help us keep the Enterprise sailing for generations to come</p></div></div>"},"elements":[]}]},{"id":"2a7c19c","elType":"container","isInner":false,"settings":{"_title":"Help Needed!","content_width":"full","css_classes":"te-block te-section","padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true},"flex_gap":{"unit":"px","size":0,"column":"0","row":"0","isLinked":true}},"elements":[{"id":"f581db8","elType":"widget","widgetType":"text-editor","isInner":false,"settings":{"_title":"Help Needed!","editor":"<section><div class="section-inner"><!-- Main appeal box --><div class="support-hero-box"><h2>Help Needed!</h2><p>Please help our small charity to buy a new, accessible, hybrid narrowboat so our fabulous team of volunteers can continue providing day trips for people who are elderly, disabled, unwell or disadvantaged on the South Staffs canals.</p><p>We are looking to replace our current boat, Enterprise, after 50 years of brilliant service to hundreds of community groups and families. A new boat will give our passengers and volunteers more modern, comfortable and convenient facilities — and our trips can continue for many years to come.</p><div style="margin: 28px 0 12px;"><div style="display:flex; justify-content:space-between; font-family:sans-serif; font-size:0.88rem; color:rgba(255,255,255,0.8); margin-bottom:8px;"><span>Raised so far: <strong style="color:var(--gold-light);">£67,000</strong></span><span>Target: <strong style="color:white;">£100,000</strong></span></div><div class="progress-bar-wrap"><div class="progress-bar-fill" style="width: 67%;"></div></div><p class="progress-label">£33,000 still needed — please help us reach our goal</p></div><a class="btn btn-gold" href="mailto:treasurer@truman-enterprise.org.uk?subject=Donation%20Enquiry" style="margin-top:8px;">Make a Donation</a></div><!-- Ways to donate --><div style="margin-top:56px; text-align:center;"><div class="section-label">How to Help</div><h2 class="section-title">Ways to Support Us</h2></div><div class="support-grid"><!-- BACS --><div class="support-card-new"><div class="icon">🏦</div><h3>BACS Transfer</h3><p>Make a direct bank transfer — the easiest way to donate. Please use your name or organisation as a reference so we can thank you.</p><div class="card-footer"><table class="bank-table"><tr><td>Bank</td><td>Unity Trust Bank</td></tr><tr><td>Account Name</td><td>Truman Enterprise NB Trust</td></tr><tr><td>Account No.</td><td>20316185</td></tr><tr><td>Sort Code</td><td>60-83-01</td></tr></table></div></div><!-- Cheque --><div class="support-card-new"><div class="icon">✉️</div><h3>Cheque</h3><p>Send a cheque payable to <strong style="color:#0d2137;">Truman Enterprise Narrowboat Trust</strong> to our Treasurer, Chris Rogers.</p><div class="card-footer"><div class="contact-box"> Contact Chris for the postal address:<br/><a href="mailto:treasurer@truman-enterprise.org.uk">treasurer@truman-enterprise.org.uk</a><br/><a href="tel:07763214524">07763 214524</a></div></div></div><!-- Donate on board --><div class="support-card-new"><div class="icon">💰</div><h3>Donate on Board</h3><p>Small or large cash donations can be made on board the Enterprise in the donation tin during your trip. Every penny goes directly towards maintaining our boat and funding future trips.</p></div><!-- Sponsor a trip --><div class="support-card-new"><div class="icon">🎯</div><h3>Sponsor a Trip</h3><p>Sponsor a boat trip for a community group who struggle to afford one. You can nominate a group, or we will find one for you. A wonderful way to give back.</p><div class="card-footer"><a class="btn btn-primary" href="mailto:enterprise@truman-enterprise.org.uk?subject=Trip%20Sponsorship%20Enquiry" style="width:100%; text-align:center; justify-content:center;">Enquire About Sponsorship</a></div></div><!-- Financial help --><div class="support-card-new"><div class="icon">📝</div><h3>Other Financial Help</h3><p>As a small charity we welcome any financial donation, large or small. Every contribution helps us maintain the boat, cover running costs, and continue providing trips for those who need them.</p><div class="card-footer"><div class="contact-box"> Contact our Treasurer for other ways of giving:<br/><a href="mailto:treasurer@truman-enterprise.org.uk">treasurer@truman-enterprise.org.uk</a></div></div></div><!-- Volunteer --><div class="support-card-new teal-border"><div class="icon">🤝</div><h3>Volunteer Your Time</h3><p>Your time and energy are just as valuable as financial support. From crewing the boat to admin and fundraising — there are many ways to get involved with our friendly team.</p><div class="card-footer"><a class="btn btn-primary" href="/get-involved/" style="width:100%; text-align:center; justify-content:center;">See Volunteering Roles</a></div></div></div></div></section>"},"elements":[]}]},{"id":"b64f683","elType":"container","isInner":false,"settings":{"_title":"Questions About Donating?","content_width":"full","css_classes":"te-block te-section","padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true},"flex_gap":{"unit":"px","size":0,"column":"0","row":"0","isLinked":true}},"elements":[{"id":"34e8a5b","elType":"widget","widgetType":"text-editor","isInner":false,"settings":{"_title":"Questions About Donating?","editor":"<section class="bg-cream"><div class="section-inner" style="text-align:center;"><div class="section-label">Get in Touch</div><h2 class="section-title">Questions About Donating?</h2><p style="font-family:sans-serif; font-size:1rem; color:var(--text-light); max-width:560px; margin:0 auto 32px;">Contact our Treasurer Chris Rogers for any queries about donations or other ways of giving.</p><div style="display:flex; gap:16px; justify-content:center; flex-wrap:wrap;"><a class="btn btn-primary" href="mailto:treasurer@truman-enterprise.org.uk">✉️ treasurer@truman-enterprise.org.uk</a><a class="btn btn-outline" href="tel:07763214524" style="border-color:var(--navy); color:var(--navy);">📞 07763 214524</a></div><p style="font-family:sans-serif; font-size:0.85rem; color:var(--text-light); margin-top:32px;"> Together, we can ensure that everyone in our community has the opportunity to experience the joy and tranquillity of our canal heritage. </p><p style="font-family:sans-serif; font-size:0.82rem; color:var(--text-light); margin-top:8px;"> Registered Charity No. 1037914  |  Member of the National Community Boats Association </p></div></section>"},"elements":[]}]},{"id":"a3796d9","elType":"container","isInner":false,"settings":{"_title":"Footer","content_width":"full","css_classes":"te-block te-footer","padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true},"flex_gap":{"unit":"px","size":0,"column":"0","row":"0","isLinked":true}},"elements":[{"id":"ad3bdef","elType":"widget","widgetType":"html","isInner":false,"settings":{"_title":"Footer + site scripts","html":"<footer><div class="footer-inner"><div class="footer-cta-strip"><div class="footer-cta-strip-text"><h3>Truman Enterprise Narrowboat Trust</h3><p>Making waterways accessible to everyone since 1968 — Registered Charity No. 1037914</p></div></div><div class="footer-grid"><div class="footer-brand"><p>A volunteer-run charity providing accessible canal boat day trips for elderly, disabled and community groups across the West Midlands since 1968.</p><span class="footer-charity-no">Registered Charity No. 1037914</span></div><div class="footer-col"><h4>Navigate</h4><ul><li><a href="/">Home</a></li><li><a href="/our-trips/">Our Trips</a></li><li><a href="/book-a-trip/">Book a Trip</a></li><li><a href="/get-involved/">Get Involved</a></li><li><a href="/support-us/">Support Us</a></li><li><a href="/contact/">Contact</a></li></ul></div><div class="footer-col"><h4>Contact Us</h4><a href="tel:07895053090">07895 053090</a><a href="mailto:enterprise@truman-enterprise.org.uk">enterprise@truman-enterprise.org.uk</a><p class="footer-address" style="margin-top:14px;">Hatherton Marina<br/>Queens Road, Calf Heath<br/>Wolverhampton WV10 7DT</p></div><div class="footer-col"><h4>Season</h4><p>Trips run <strong style="color:rgba(255,255,255,0.7);">April to October</strong>, 7 days a week, from Hatherton Marina.</p><p style="margin-top:16px;"><span class="ncba-badge">🚢 NCBA Member</span></p></div></div><div class="footer-bottom"><p>© 2025 Truman Enterprise Narrowboat Trust. Registered Charity No. 1037914.</p><p>Member of the National Community Boats Association</p></div></div></footer>
<script>
// =============================================
// Truman Enterprise Narrowboat Trust - JS
// =============================================

// ---- Navigation hamburger ----
(function (init) { if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init(); })(function () {
  const hamburger = document.querySelector('.nav-hamburger');
  const navLinks = document.querySelector('.nav-links');
  if (hamburger && navLinks) {
    hamburger.addEventListener('click', function () {
      navLinks.classList.toggle('open');
    });
    document.addEventListener('click', function (e) {
      if (!e.target.closest('nav')) navLinks.classList.remove('open');
    });
  }


  // Init all components
  initHeroSlider();
  initAccordions();
  initCalendar();
  initBookingForm();
  animateStats();
});

// ---- Hero Slider ----
function initHeroSlider() {
  const slides = document.querySelectorAll('.hero-slide');
  const dots = document.querySelectorAll('.hero-dot');
  if (!slides.length) return;

  let current = 0;
  let timer = null;

  function goTo(idx) {
    slides[current].classList.remove('active');
    if (dots[current]) dots[current].classList.remove('active');
    current = (idx + slides.length) % slides.length;
    slides[current].classList.add('active');
    if (dots[current]) dots[current].classList.add('active');
  }

  function start() { timer = setInterval(() => goTo(current + 1), 5000); }
  function reset() { clearInterval(timer); start(); }

  dots.forEach((dot, i) => dot.addEventListener('click', () => { goTo(i); reset(); }));

  slides[0].classList.add('active');
  if (dots[0]) dots[0].classList.add('active');
  if (slides.length > 1) start();
}

// ---- Accordions ----
function initAccordions() {
  document.querySelectorAll('.accordion-header').forEach(header => {
    header.addEventListener('click', function () {
      const body = this.nextElementSibling;
      const isOpen = this.classList.contains('open');

      // Close all in this accordion group
      const accordion = this.closest('.accordion');
      if (accordion) {
        accordion.querySelectorAll('.accordion-header').forEach(h => {
          h.classList.remove('open');
          h.nextElementSibling.classList.remove('open');
        });
      }

      if (!isOpen) {
        this.classList.add('open');
        body.classList.add('open');
      }
    });
  });
}

// ---- Calendar ----
const TRIP_DATA = {
  // Format: 'YYYY-MM-DD': 'available' | 'provisional' | 'booked'
  // These are example dates - in production these would come from a backend
};

// Generate sample data for April-October of current year
(function seedCalendar() {
  const year = new Date().getFullYear();
  const months = [3, 4, 5, 6, 7, 8, 9]; // Apr-Oct (0-indexed)
  const statuses = ['available', 'available', 'available', 'provisional', 'booked'];
  months.forEach(m => {
    const daysInMonth = new Date(year, m + 1, 0).getDate();
    for (let d = 1; d <= daysInMonth; d++) {
      if ([0, 6].includes(new Date(year, m, d).getDay())) continue; // skip some
      if (Math.random() > 0.45) {
        const key = `${year}-${String(m + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        TRIP_DATA[key] = statuses[Math.floor(Math.random() * statuses.length)];
      }
    }
  });
})();

function initCalendar() {
  const wrapper = document.getElementById('booking-calendar');
  if (!wrapper) return;

  const today = new Date();
  let viewYear = today.getFullYear();
  let viewMonth = today.getMonth(); // Start at current month

  // Start at April if current month is before April
  if (viewMonth < 3) viewMonth = 3;

  renderCalendar(wrapper, viewYear, viewMonth);

  wrapper.querySelector('.cal-prev').addEventListener('click', () => {
    viewMonth--;
    if (viewMonth < 0) { viewMonth = 11; viewYear--; }
    renderCalendar(wrapper, viewYear, viewMonth);
  });

  wrapper.querySelector('.cal-next').addEventListener('click', () => {
    viewMonth++;
    if (viewMonth > 11) { viewMonth = 0; viewYear++; }
    renderCalendar(wrapper, viewYear, viewMonth);
  });
}

function renderCalendar(wrapper, year, month) {
  const monthNames = ['January','February','March','April','May','June',
                      'July','August','September','October','November','December'];
  const today = new Date();

  wrapper.querySelector('.cal-month-label').textContent = `${monthNames[month]} ${year}`;

  const daysContainer = wrapper.querySelector('.calendar-days');
  daysContainer.innerHTML = '';

  const firstDay = new Date(year, month, 1).getDay();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const prevDays = new Date(year, month, 0).getDate();

  // Monday-first offset
  const offset = (firstDay + 6) % 7;

  // Prev month padding
  for (let i = offset - 1; i >= 0; i--) {
    const btn = document.createElement('button');
    btn.className = 'cal-day other-month';
    btn.textContent = prevDays - i;
    daysContainer.appendChild(btn);
  }

  // Current month days
  for (let d = 1; d <= daysInMonth; d++) {
    const dateKey = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
    const status = TRIP_DATA[dateKey];
    const btn = document.createElement('button');
    btn.className = 'cal-day';
    btn.textContent = d;

    if (status) btn.classList.add(status);

    const isToday = d === today.getDate() && month === today.getMonth() && year === today.getFullYear();
    if (isToday) btn.classList.add('today');

    if (status === 'available') {
      btn.title = 'Available - click to book';
      btn.addEventListener('click', () => {
        const bookingSection = document.getElementById('booking-section');
        if (bookingSection) {
          bookingSection.scrollIntoView({ behavior: 'smooth' });
          // Pre-fill date if form exists
          const dateInput = document.querySelector('input[name="trip1_date"]');
          if (dateInput) {
            dateInput.value = dateKey;
          }
        }
      });
    } else if (status === 'booked') {
      btn.title = 'Fully booked';
    } else if (status === 'provisional') {
      btn.title = 'Provisional booking - contact us to enquire';
    }

    daysContainer.appendChild(btn);
  }

  // Next month padding
  const total = offset + daysInMonth;
  const remaining = total % 7 === 0 ? 0 : 7 - (total % 7);
  for (let d = 1; d <= remaining; d++) {
    const btn = document.createElement('button');
    btn.className = 'cal-day other-month';
    btn.textContent = d;
    daysContainer.appendChild(btn);
  }
}

// ---- Booking Form ----
function initBookingForm() {
  const form = document.getElementById('booking-form');
  if (!form) return;

  form.addEventListener('submit', function (e) {
    e.preventDefault();

    const terms = form.querySelector('input[name="terms"]');
    if (!terms || !terms.checked) {
      alert('Please read and agree to the Terms and Conditions before submitting.');
      return;
    }

    // Collect form data
    const data = new FormData(form);
    const subject = `Boat Trip Booking - ${data.get('group_name') || 'New Booking'}`;
    const body = buildEmailBody(data);

    // Open mailto link
    const mailto = `mailto:enterprise@truman-enterprise.org.uk?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
    window.location.href = mailto;

    const success = form.querySelector('.success-message');
    if (success) success.style.display = 'block';
  });
}

function buildEmailBody(data) {
  let body = 'TRIP BOOKING REQUEST\n';
  body += '====================\n\n';
  body += `Group Name: ${data.get('group_name') || ''}\n`;
  body += `Contact Name: ${data.get('contact_name') || ''}\n`;
  body += `Address: ${data.get('address') || ''}\n`;
  body += `Phone: ${data.get('phone') || ''}\n`;
  body += `Email: ${data.get('email') || ''}\n`;
  body += `Day-of Contact: ${data.get('day_contact') || ''}\n`;
  body += `Day-of Mobile: ${data.get('day_mobile') || ''}\n\n`;
  body += 'TRIPS REQUESTED:\n';
  for (let i = 1; i <= 3; i++) {
    const date = data.get(`trip${i}_date`);
    const dest = data.get(`trip${i}_dest`);
    const lunch = data.get(`trip${i}_lunch`);
    if (date || dest) {
      body += `  Trip ${i}: Date: ${date || '—'} | Destination: ${dest || '—'} | Lunch: ${lunch || '—'}\n`;
    }
  }
  body += `\nPhotos consent: ${data.get('photos') ? 'Yes' : 'No'}\n`;
  return body;
}

// ---- Stats counter animation ----
function animateStats() {
  const stats = document.querySelectorAll('.stat-number[data-target]');
  if (!stats.length) return;

  const observer = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        const el = entry.target;
        const target = parseInt(el.dataset.target);
        const suffix = el.dataset.suffix || '';
        let current = 0;
        const step = Math.ceil(target / 50);
        const interval = setInterval(() => {
          current = Math.min(current + step, target);
          el.textContent = current.toLocaleString() + suffix;
          if (current >= target) clearInterval(interval);
        }, 30);
        observer.unobserve(el);
      }
    });
  }, { threshold: 0.5 });

  stats.forEach(stat => observer.observe(stat));
}

</script>"},"elements":[]}]}]

