_classes":"te-block te-section","padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true},"flex_gap":{"unit":"px","size":0,"column":"0","row":"0","isLinked":true}},"elements":[{"id":"005b98b","elType":"widget","widgetType":"text-editor","isInner":false,"settings":{"_title":"Page banner","editor":"<div class="page-hero" style="position:relative;min-height:520px;overflow:hidden;display:flex;align-items:flex-end;width:100%;"><img alt="Volunteers on the canal" src="/wp-content/uploads/2026/10/truman-volunteers-canal.jpg" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center 40%;display:block;"/><div class="page-hero-content"><h1>Book a Trip</h1><p>Complete the form below to request your canal boat day out</p></div></div>"},"elements":[]}]},{"id":"6032687","elType":"container","isInner":false,"settings":{"_title":"Trip Booking Request","content_width":"full","css_classes":"te-block te-section","padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true},"flex_gap":{"unit":"px","size":0,"column":"0","row":"0","isLinked":true}},"elements":[{"id":"57755da","elType":"widget","widgetType":"html","isInner":false,"settings":{"_title":"Trip Booking Request","html":"<section><div class="section-inner"><div class="booking-layout"><!-- Booking Form --><div class="form-card"><h2>Trip Booking Request</h2><p class="form-subtitle">You can book up to 3 trips on this form. We'll confirm your booking by email and send an invoice.</p><p class="required-note"><span>*</span> Required fields</p><form id="booking-form" novalidate=""><div class="form-section-title">Your Details</div><div class="form-group"><label for="group_name">Group / Organisation Name <span style="color:var(--red)">*</span></label><input id="group_name" name="group_name" placeholder="e.g. Sunflower Day Centre" required="" type="text"/></div><div class="form-row"><div class="form-group"><label for="contact_name">Contact Name <span style="color:var(--red)">*</span></label><input id="contact_name" name="contact_name" placeholder="Full name" required="" type="text"/></div><div class="form-group"><label for="phone">Phone Number <span style="color:var(--red)">*</span></label><input id="phone" name="phone" placeholder="07xxx xxxxxx" required="" type="tel"/></div></div><div class="form-group"><label for="address">Postal Address <span style="color:var(--red)">*</span></label><textarea id="address" name="address" placeholder="Street, Town, Postcode" required="" rows="3"></textarea></div><div class="form-group"><label for="email">Email Address <span style="color:var(--red)">*</span></label><input id="email" name="email" placeholder="you@example.com" required="" type="email"/></div><div class="form-section-title">Contact on the Day of Trip</div><div class="form-row"><div class="form-group"><label for="day_contact">Name of Contact on Day</label><input id="day_contact" name="day_contact" placeholder="If different from above" type="text"/></div><div class="form-group"><label for="day_mobile">Mobile Number (optional)</label><input id="day_mobile" name="day_mobile" placeholder="07xxx xxxxxx" type="tel"/></div></div><div class="form-section-title">Your Trip Choices</div><p style="font-family:sans-serif; font-size:0.85rem; color:var(--text-light); margin-bottom:20px;"> Please check the <a href="/our-trips/#booking-calendar" style="color:var(--teal);">availability calendar</a> before selecting your dates. Trips run April–October. </p><!-- Trip rows 1–6 --><div id="trip-rows"><div class="trip-row"><div class="trip-row-header"><div class="trip-row-num">1</div> Trip 1</div><div class="form-row" style="grid-template-columns:1fr 1fr 1fr;"><div class="form-group" style="margin-bottom:0;"><label>Date</label><input name="trip1_date" type="date"/></div><div class="form-group" style="margin-bottom:0;"><label>Destination</label><select name="trip1_dest"><option value="">— Select —</option><option value="Coven £110">Coven (£110)</option><option value="Autherley £140">Autherley (£140)</option><option value="Penkridge £170">Penkridge (£170)</option></select></div><div class="form-group" style="margin-bottom:0;"><label>Lunch Option</label><select name="trip1_lunch"><option value="">— Select —</option><option value="Own food">Own food</option><option value="Fish &amp; chips">Fish &amp; chips</option><option value="Pub lunch">Pub lunch (Coven only)</option><option value="Cross Keys take-away">Cross Keys take-away (Penkridge)</option></select></div></div></div><div class="trip-row"><div class="trip-row-header"><div class="trip-row-num">2</div> Trip 2</div><div class="form-row" style="grid-template-columns:1fr 1fr 1fr;"><div class="form-group" style="margin-bottom:0;"><label>Date</label><input name="trip2_date" type="date"/></div><div class="form-group" style="margin-bottom:0;"><label>Destination</label><select name="trip2_dest"><option value="">— Select —</option><option value="Coven £110">Coven (£110)</option><option value="Autherley £140">Autherley (£140)</option><option value="Penkridge £170">Penkridge (£170)</option></select></div><div class="form-group" style="margin-bottom:0;"><label>Lunch Option</label><select name="trip2_lunch"><option value="">— Select —</option><option value="Own food">Own food</option><option value="Fish &amp; chips">Fish &amp; chips</option><option value="Pub lunch">Pub lunch (Coven only)</option><option value="Cross Keys take-away">Cross Keys take-away (Penkridge)</option></select></div></div></div><div class="trip-row"><div class="trip-row-header"><div class="trip-row-num">3</div> Trip 3</div><div class="form-row" style="grid-template-columns:1fr 1fr 1fr;"><div class="form-group" style="margin-bottom:0;"><label>Date</label><input name="trip3_date" type="date"/></div><div class="form-group" style="margin-bottom:0;"><label>Destination</label><select name="trip3_dest"><option value="">— Select —</option><option value="Coven £110">Coven (£110)</option><option value="Autherley £140">Autherley (£140)</option><option value="Penkridge £170">Penkridge (£170)</option></select></div><div class="form-group" style="margin-bottom:0;"><label>Lunch Option</label><select name="trip3_lunch"><option value="">— Select —</option><option value="Own food">Own food</option><option value="Fish &amp; chips">Fish &amp; chips</option><option value="Pub lunch">Pub lunch (Coven only)</option><option value="Cross Keys take-away">Cross Keys take-away (Penkridge)</option></select></div></div></div></div><div class="form-section-title">Confirmation</div><div class="checkbox-group"><input id="terms" name="terms" required="" type="checkbox"/><label for="terms">I have read and agree to the <a href="#" style="color:var(--teal);">Terms and Conditions</a>. I understand that payment is due 28 days before each trip and the price does not include food. <span style="color:var(--red);">*</span></label></div><div class="checkbox-group"><input id="photos" name="photos" type="checkbox"/><label for="photos">I am happy for photos to be taken of our group during the trip, which may be used in the Trust's publicity materials.</label></div><button class="btn btn-primary" style="width:100%; padding:16px; font-size:1rem; margin-top:8px;" type="submit"> Submit Booking Request </button><div class="success-message" style="display:none;"> ✅ Thank you! Your booking request has been prepared. Please send the email that has opened in your mail app, or contact us directly at <a href="mailto:enterprise@truman-enterprise.org.uk" style="color:var(--teal);">enterprise@truman-enterprise.org.uk</a> or <a href="tel:07895053090" style="color:var(--teal);">07895 053090</a>. </div></form></div><!-- Side Info Panel --><div><div style="background:var(--navy); color:white; border-radius:12px; padding:32px; margin-bottom:24px;"><h3 style="font-size:1.2rem; margin-bottom:20px; color:white;">Trip Prices</h3><div style="display:flex; flex-direction:column; gap:12px;"><div style="display:flex; justify-content:space-between; align-items:center; padding-bottom:12px; border-bottom:1px solid rgba(255,255,255,0.1);"><div><div style="font-family:sans-serif; font-weight:600; font-size:0.9rem;">🍺 Coven</div><div style="font-family:sans-serif; font-size:0.78rem; color:rgba(255,255,255,0.6);">5–5½ hours</div></div><div style="color:var(--gold); font-size:1.3rem; font-weight:bold;">£110</div></div><div style="display:flex; justify-content:space-between; align-items:center; padding-bottom:12px; border-bottom:1px solid rgba(255,255,255,0.1);"><div><div style="font-family:sans-serif; font-weight:600; font-size:0.9rem;">⚓ Autherley</div><div style="font-family:sans-serif; font-size:0.78rem; color:rgba(255,255,255,0.6);">6 hours</div></div><div style="color:var(--gold); font-size:1.3rem; font-weight:bold;">£140</div></div><div style="display:flex; justify-content:space-between; align-items:center;"><div><div style="font-family:sans-serif; font-weight:600; font-size:0.9rem;">🔒 Penkridge</div><div style="font-family:sans-serif; font-size:0.78rem; color:rgba(255,255,255,0.6);">8 hours · 12 locks</div></div><div style="color:var(--gold); font-size:1.3rem; font-weight:bold;">£170</div></div></div><p style="font-family:sans-serif; font-size:0.78rem; color:rgba(255,255,255,0.5); margin-top:16px; border-top:1px solid rgba(255,255,255,0.1); padding-top:12px;"> Prices are per trip for up to 12 passengers. Minimum 2 group leaders/staff required. Food costs are not included. </p></div><div style="background:white; border-radius:12px; padding:28px; box-shadow:var(--shadow); margin-bottom:24px;"><h3 style="font-size:1rem; color:var(--navy); margin-bottom:16px;">Need Help Booking?</h3><p style="font-family:sans-serif; font-size:0.85rem; color:var(--text-light); margin-bottom:16px; line-height:1.6;">If you have any queries about your trip or completing this form, please contact our bookings secretary:</p><div class="contact-item" style="margin-bottom:10px;"><span class="contact-icon">📞</span><a href="tel:07895053090" style="color:var(--navy); font-family:sans-serif; font-size:0.9rem; font-weight:600; text-decoration:none;">07895 053090</a></div><div class="contact-item"><span class="contact-icon">✉️</span><a href="mailto:enterprise@truman-enterprise.org.uk" style="color:var(--teal); font-family:sans-serif; font-size:0.82rem; text-decoration:none;">enterprise@truman-enterprise.org.uk</a></div></div><div class="info-box"><strong>📅 Season:</strong> Trips run April to October, 7 days a week.<br/><br/><strong>💳 Payment:</strong> Due 28 days before each trip. Payable by cheque or BACS (details on invoice).<br/><br/><strong>📍 Start point:</strong> Hatherton Marina, Queens Road, Calf Heath, Wolverhampton WV10 7DT.<br/><br/><strong>♿ Accessibility:</strong> Up to 2 wheelchair users per trip. Ramp and hydraulic lift available. </div><div style="background:white; border-radius:12px; padding:28px; box-shadow:var(--shadow); margin-top:24px;"><h3 style="font-size:1rem; color:var(--navy); margin-bottom:12px;">📍 Getting Here</h3><p style="font-family:sans-serif; font-size:0.85rem; color:var(--text-light); line-height:1.7;"> Hatherton Marina<br/>Queens Road, Calf Heath<br/>Wolverhampton <strong>WV10 7DT</strong></p><div class="what3words" style="display:inline-flex; margin-top:8px;">/// clarifies.overhead.paths</div><p style="font-family:sans-serif; font-size:0.82rem; color:var(--text-light); margin-top:12px;">Free secure parking available at the Marina. Vehicles can offload near the boat.</p><a class="btn btn-primary" href="https://maps.google.com/?q=Hatherton+Marina+Queens+Road+Calf+Heath+Wolverhampton+WV10+7DT" style="margin-top:12px; padding:10px 16px; font-size:0.85rem; display:inline-block;" target="_blank"> Open in Google Maps </a></div></div></div></div></section>"},"elements":[]}]},{"id":"678bd1f","elType":"container","isInner":false,"settings":{"_title":"Footer","content_width":"full","css_classes":"te-block te-footer","padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true},"flex_gap":{"unit":"px","size":0,"column":"0","row":"0","isLinked":true}},"elements":[{"id":"db37b7c","elType":"widget","widgetType":"html","isInner":false,"settings":{"_title":"Footer + site scripts","html":"<footer><div class="footer-inner"><div class="footer-cta-strip"><div class="footer-cta-strip-text"><h3>Truman Enterprise Narrowboat Trust</h3><p>Making waterways accessible to everyone since 1968 — Registered Charity No. 1037914</p></div></div><div class="footer-grid"><div class="footer-brand"><p>A volunteer-run charity providing accessible canal boat day trips for elderly, disabled and community groups across the West Midlands since 1968.</p><span class="footer-charity-no">Registered Charity No. 1037914</span></div><div class="footer-col"><h4>Navigate</h4><ul><li><a href="/">Home</a></li><li><a href="/our-trips/">Our Trips</a></li><li><a href="/book-a-trip/">Book a Trip</a></li><li><a href="/get-involved/">Get Involved</a></li><li><a href="/support-us/">Support Us</a></li><li><a href="/contact/">Contact</a></li></ul></div><div class="footer-col"><h4>Contact Us</h4><a href="tel:07895053090">07895 053090</a><a href="mailto:enterprise@truman-enterprise.org.uk">enterprise@truman-enterprise.org.uk</a><p class="footer-address" style="margin-top:14px;">Hatherton Marina<br/>Queens Road, Calf Heath<br/>Wolverhampton WV10 7DT</p></div><div class="footer-col"><h4>Season</h4><p>Trips run <strong style="color:rgba(255,255,255,0.7);">April to October</strong>, 7 days a week, from Hatherton Marina.</p><p style="margin-top:16px;"><span class="ncba-badge">🚢 NCBA Member</span></p></div></div><div class="footer-bottom"><p>© 2025 Truman Enterprise Narrowboat Trust. Registered Charity No. 1037914.</p><p>Member of the National Community Boats Association</p></div></div></footer>
<script>
// =============================================
// Truman Enterprise Narrowboat Trust - JS
// =============================================

// ---- Navigation hamburger ----
(function (init) { if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init(); })(function () {
  const hamburger = document.querySelector('.nav-hamburger');
  const navLinks = document.querySelector('.nav-links');
  if (hamburger && navLinks) {
    hamburger.addEventListener('click', function () {
      navLinks.classList.toggle('open');
    });
    document.addEventListener('click', function (e) {
      if (!e.target.closest('nav')) navLinks.classList.remove('open');
    });
  }


  // Init all components
  initHeroSlider();
  initAccordions();
  initCalendar();
  initBookingForm();
  animateStats();
});

// ---- Hero Slider ----
function initHeroSlider() {
  const slides = document.querySelectorAll('.hero-slide');
  const dots = document.querySelectorAll('.hero-dot');
  if (!slides.length) return;

  let current = 0;
  let timer = null;

  function goTo(idx) {
    slides[current].classList.remove('active');
    if (dots[current]) dots[current].classList.remove('active');
    current = (idx + slides.length) % slides.length;
    slides[current].classList.add('active');
    if (dots[current]) dots[current].classList.add('active');
  }

  function start() { timer = setInterval(() => goTo(current + 1), 5000); }
  function reset() { clearInterval(timer); start(); }

  dots.forEach((dot, i) => dot.addEventListener('click', () => { goTo(i); reset(); }));

  slides[0].classList.add('active');
  if (dots[0]) dots[0].classList.add('active');
  if (slides.length > 1) start();
}

// ---- Accordions ----
function initAccordions() {
  document.querySelectorAll('.accordion-header').forEach(header => {
    header.addEventListener('click', function () {
      const body = this.nextElementSibling;
      const isOpen = this.classList.contains('open');

      // Close all in this accordion group
      const accordion = this.closest('.accordion');
      if (accordion) {
        accordion.querySelectorAll('.accordion-header').forEach(h => {
          h.classList.remove('open');
          h.nextElementSibling.classList.remove('open');
        });
      }

      if (!isOpen) {
        this.classList.add('open');
        body.classList.add('open');
      }
    });
  });
}

// ---- Calendar ----
const TRIP_DATA = {
  // Format: 'YYYY-MM-DD': 'available' | 'provisional' | 'booked'
  // These are example dates - in production these would come from a backend
};

// Generate sample data for April-October of current year
(function seedCalendar() {
  const year = new Date().getFullYear();
  const months = [3, 4, 5, 6, 7, 8, 9]; // Apr-Oct (0-indexed)
  const statuses = ['available', 'available', 'available', 'provisional', 'booked'];
  months.forEach(m => {
    const daysInMonth = new Date(year, m + 1, 0).getDate();
    for (let d = 1; d <= daysInMonth; d++) {
      if ([0, 6].includes(new Date(year, m, d).getDay())) continue; // skip some
      if (Math.random() > 0.45) {
        const key = `${year}-${String(m + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        TRIP_DATA[key] = statuses[Math.floor(Math.random() * statuses.length)];
      }
    }
  });
})();

function initCalendar() {
  const wrapper = document.getElementById('booking-calendar');
  if (!wrapper) return;

  const today = new Date();
  let viewYear = today.getFullYear();
  let viewMonth = today.getMonth(); // Start at current month

  // Start at April if current month is before April
  if (viewMonth < 3) viewMonth = 3;

  renderCalendar(wrapper, viewYear, viewMonth);

  wrapper.querySelector('.cal-prev').addEventListener('click', () => {
    viewMonth--;
    if (viewMonth < 0) { viewMonth = 11; viewYear--; }
    renderCalendar(wrapper, viewYear, viewMonth);
  });

  wrapper.querySelector('.cal-next').addEventListener('click', () => {
    viewMonth++;
    if (viewMonth > 11) { viewMonth = 0; viewYear++; }
    renderCalendar(wrapper, viewYear, viewMonth);
  });
}

function renderCalendar(wrapper, year, month) {
  const monthNames = ['January','February','March','April','May','June',
                      'July','August','September','October','November','December'];
  const today = new Date();

  wrapper.querySelector('.cal-month-label').textContent = `${monthNames[month]} ${year}`;

  const daysContainer = wrapper.querySelector('.calendar-days');
  daysContainer.innerHTML = '';

  const firstDay = new Date(year, month, 1).getDay();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const prevDays = new Date(year, month, 0).getDate();

  // Monday-first offset
  const offset = (firstDay + 6) % 7;

  // Prev month padding
  for (let i = offset - 1; i >= 0; i--) {
    const btn = document.createElement('button');
    btn.className = 'cal-day other-month';
    btn.textContent = prevDays - i;
    daysContainer.appendChild(btn);
  }

  // Current month days
  for (let d = 1; d <= daysInMonth; d++) {
    const dateKey = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
    const status = TRIP_DATA[dateKey];
    const btn = document.createElement('button');
    btn.className = 'cal-day';
    btn.textContent = d;

    if (status) btn.classList.add(status);

    const isToday = d === today.getDate() && month === today.getMonth() && year === today.getFullYear();
    if (isToday) btn.classList.add('today');

    if (status === 'available') {
      btn.title = 'Available - click to book';
      btn.addEventListener('click', () => {
        const bookingSection = document.getElementById('booking-section');
        if (bookingSection) {
          bookingSection.scrollIntoView({ behavior: 'smooth' });
          // Pre-fill date if form exists
          const dateInput = document.querySelector('input[name="trip1_date"]');
          if (dateInput) {
            dateInput.value = dateKey;
          }
        }
      });
    } else if (status === 'booked') {
      btn.title = 'Fully booked';
    } else if (status === 'provisional') {
      btn.title = 'Provisional booking - contact us to enquire';
    }

    daysContainer.appendChild(btn);
  }

  // Next month padding
  const total = offset + daysInMonth;
  const remaining = total % 7 === 0 ? 0 : 7 - (total % 7);
  for (let d = 1; d <= remaining; d++) {
    const btn = document.createElement('button');
    btn.className = 'cal-day other-month';
    btn.textContent = d;
    daysContainer.appendChild(btn);
  }
}

// ---- Booking Form ----
function initBookingForm() {
  const form = document.getElementById('booking-form');
  if (!form) return;

  form.addEventListener('submit', function (e) {
    e.preventDefault();

    const terms = form.querySelector('input[name="terms"]');
    if (!terms || !terms.checked) {
      alert('Please read and agree to the Terms and Conditions before submitting.');
      return;
    }

    // Collect form data
    const data = new FormData(form);
    const subject = `Boat Trip Booking - ${data.get('group_name') || 'New Booking'}`;
    const body = buildEmailBody(data);

    // Open mailto link
    const mailto = `mailto:enterprise@truman-enterprise.org.uk?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
    window.location.href = mailto;

    const success = form.querySelector('.success-message');
    if (success) success.style.display = 'block';
  });
}

function buildEmailBody(data) {
  let body = 'TRIP BOOKING REQUEST\n';
  body += '====================\n\n';
  body += `Group Name: ${data.get('group_name') || ''}\n`;
  body += `Contact Name: ${data.get('contact_name') || ''}\n`;
  body += `Address: ${data.get('address') || ''}\n`;
  body += `Phone: ${data.get('phone') || ''}\n`;
  body += `Email: ${data.get('email') || ''}\n`;
  body += `Day-of Contact: ${data.get('day_contact') || ''}\n`;
  body += `Day-of Mobile: ${data.get('day_mobile') || ''}\n\n`;
  body += 'TRIPS REQUESTED:\n';
  for (let i = 1; i <= 3; i++) {
    const date = data.get(`trip${i}_date`);
    const dest = data.get(`trip${i}_dest`);
    const lunch = data.get(`trip${i}_lunch`);
    if (date || dest) {
      body += `  Trip ${i}: Date: ${date || '—'} | Destination: ${dest || '—'} | Lunch: ${lunch || '—'}\n`;
    }
  }
  body += `\nPhotos consent: ${data.get('photos') ? 'Yes' : 'No'}\n`;
  return body;
}

// ---- Stats counter animation ----
function animateStats() {
  const stats = document.querySelectorAll('.stat-number[data-target]');
  if (!stats.length) return;

  const observer = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        const el = entry.target;
        const target = parseInt(el.dataset.target);
        const suffix = el.dataset.suffix || '';
        let current = 0;
        const step = Math.ceil(target / 50);
        const interval = setInterval(() => {
          current = Math.min(current + step, target);
          el.textContent = current.toLocaleString() + suffix;
          if (current >= target) clearInterval(interval);
        }, 30);
        observer.unobserve(el);
      }
    });
  }, { threshold: 0.5 });

  stats.forEach(stat => observer.observe(stat));
}

</script>"},"elements":[]}]}]

item.content:encoded:
/* Truman Enterprise Narrowboat Trust — site styles
   Generated from css/style.css by wordpress/build.py. Applies to the Elementor pages
   (every page section has the class "te-block"). */
@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,600;0,700;1,400;1,600&family=Inter:wght@300;400;500;600;700&display=swap');
:root {--navy:       #0d2137;
  --navy-mid:   #163350;
  --teal:       #1a6e62;
  --teal-light: #22897b;
  --teal-pale:  #e8f5f3;
  --gold:       #b8852a;
  --gold-light: #f0c060;
  --red:        #c0392b;
  --cream:      #f9f6f1;
  --off-white:  #fdfcfa;
  --text:       #1a1a2e;
  --text-mid:   #3d4a5c;
  --text-light: #6b7a8d;
  --border:     #e2e8f0;
  --shadow-sm:  0 1px 4px rgba(13,33,55,0.08);
  --shadow-md:  0 4px 16px rgba(13,33,55,0.10);
  --shadow-lg:  0 12px 40px rgba(13,33,55,0.14);
  --radius:     10px;
  --radius-lg:  16px;}
.te-block *, .te-block *::before, .te-block *::after {box-sizing: border-box; margin: 0; padding: 0;}
html {scroll-behavior: smooth;}
body, .te-block {font-family: 'Inter', system-ui, sans-serif;
  color: var(--text);
  background: var(--off-white);
  line-height: 1.75;
  font-size: 16px;
  -webkit-font-smoothing: antialiased;}
.te-block h1, .te-block h2, .te-block h3 {font-family: 'Playfair Display', Georgia, serif; line-height: 1.25;}
.te-block h4, .te-block h5, .te-block h6, .te-block label, .te-block button {font-family: 'Inter', sans-serif;}
.te-block .serif {font-family: 'Playfair Display', Georgia, serif;}
.te-block .sans {font-family: 'Inter', sans-serif;}
.te-block nav {background: var(--navy);
  position: sticky;
  top: 0;
  z-index: 1000;
  border-bottom: 1px solid rgba(255,255,255,0.06);}
.te-block .nav-inner {max-width: 1280px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 32px;
  height: 72px;}
.te-block .nav-logo {display: flex;
  align-items: center;
  gap: 14px;
  text-decoration: none;
  flex-shrink: 0;}
.te-block .nav-logo-icon {width: 44px; height: 44px; flex-shrink: 0;}
.te-block .nav-logo-text span:first-child {display: block;
  font-family: 'Playfair Display', serif;
  font-size: 1.05rem;
  color: white;
  letter-spacing: 0.2px;
  line-height: 1.2;}
.te-block .nav-logo-text span:last-child {display: block;
  font-family: 'Inter', sans-serif;
  font-size: 0.65rem;
  color: var(--gold-light);
  letter-spacing: 2px;
  text-transform: uppercase;}
.te-block .nav-links {display: flex;
  list-style: none;
  align-items: center;
  gap: 2px;}
.te-block .nav-links a {display: block;
  color: rgba(255,255,255,0.92);
  text-decoration: none;
  padding: 8px 14px;
  font-size: 0.8rem;
  font-weight: 500;
  letter-spacing: 0.8px;
  text-transform: uppercase;
  border-radius: 6px;
  transition: color 0.2s, background 0.2s;}
.te-block .nav-links a:hover {color: white; background: rgba(255,255,255,0.07);}
.te-block .nav-links a.active {color: white;
  background: rgba(255,255,255,0.08);
  border-bottom: 2px solid var(--gold-light);
  border-radius: 6px 6px 0 0;
  padding-bottom: 6px;}
.te-block .nav-cta {background: var(--teal) !important;
  color: white !important;
  border-radius: 6px !important;
  padding: 9px 20px !important;
  margin-left: 10px;
  font-weight: 600 !important;
  letter-spacing: 0.5px !important;
  border-bottom: none !important;
  border-radius: 6px !important;}
.te-block .nav-cta:hover {background: var(--teal-light) !important;}
.te-block .nav-cta.active {border-bottom: none !important; padding-bottom: 9px !important;}
.te-block .nav-hamburger {display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 8px;}
.te-block .nav-hamburger span {display: block; width: 22px; height: 2px;
  background: rgba(255,255,255,0.8); transition: all 0.3s; border-radius: 2px;}
.te-block .hero {position: relative;
  min-height: 600px;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;}
.te-block .hero-slide {position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  width: 100%; height: 100%;
  background-size: cover;
  background-position: center center;
  background-repeat: no-repeat;
  opacity: 0;
  transition: opacity 1.2s ease-in-out, transform 8s ease-out;
  transform: scale(1.03);
  will-change: opacity, transform;}
.te-block .hero-slide.active {opacity: 1; transform: scale(1);}
.te-block .hero-overlay {position: absolute; inset: 0;
  background: linear-gradient(
    160deg,
    rgba(8, 22, 38, 0.75) 0%,
    rgba(8, 22, 38, 0.50) 55%,
    rgba(8, 22, 38, 0.35) 100%
  );
  pointer-events: none;}
.te-block .hero-content {position: relative;
  z-index: 2;
  max-width: 720px;
  width: 100%;
  padding: 100px 32px 80px;
  text-align: left;}
.te-block .hero-eyebrow {display: inline-block;
  font-family: 'Inter', sans-serif;
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 3px;
  text-transform: uppercase;
  color: var(--gold-light);
  margin-bottom: 16px;
  padding: 5px 12px;
  border: 1px solid rgba(240,192,96,0.35);
  border-radius: 50px;
  backdrop-filter: blur(4px);
  background: rgba(184,133,42,0.12);}
.te-block .hero-content h1 {font-size: clamp(1.8rem, 5vw, 3.8rem);
  color: white;
  line-height: 1.15;
  margin-bottom: 16px;
  text-shadow: 0 2px 12px rgba(0,0,0,0.3);
  font-weight: 700;}
.te-block .hero-content h1 em {font-style: italic;
  color: var(--gold-light);}
.te-block .hero-content p {font-size: clamp(0.92rem, 2vw, 1.15rem);
  color: rgba(255,255,255,0.88);
  margin-bottom: 28px;
  font-weight: 300;
  max-width: 520px;
  line-height: 1.7;}
.te-block .hero-actions {display: flex; gap: 14px; flex-wrap: wrap;}
.te-block .hero-dots {position: absolute;
  bottom: 28px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  gap: 8px;
  z-index: 3;}
.te-block .hero-dot {width: 6px; height: 6px;
  border-radius: 50%;
  background: rgba(255,255,255,0.35);
  border: none; cursor: pointer;
  transition: all 0.3s;}
.te-block .hero-dot.active {background: white; width: 24px; border-radius: 3px;}
.te-block .page-hero {position: relative;
  min-height: 520px;
  display: flex;
  align-items: flex-end;
  width: 100%;
  overflow: hidden;}
.te-block .page-hero-img {position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 40%;
  display: block;}
.te-block .page-hero::after {content: '';
  position: absolute; inset: 0;
  background: linear-gradient(to top, rgba(8,22,38,0.88) 0%, rgba(8,22,38,0.4) 50%, rgba(8,22,38,0.15) 100%);
  pointer-events: none;
  z-index: 1;}
.te-block .page-hero-content {position: relative;
  z-index: 2;
  padding: 40px 56px;
  color: white;
  max-width: 800px;
  width: 100%;}
.te-block .page-hero-content .eyebrow {font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 3px;
  text-transform: uppercase;
  color: var(--gold-light);
  margin-bottom: 10px;
  display: block;}
.te-block .page-hero-content h1 {font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 700;
  text-shadow: 0 2px 8px rgba(0,0,0,0.4);
  line-height: 1.15;}
.te-block .page-hero-content p {font-size: 1.05rem;
  color: rgba(255,255,255,0.82);
  margin-top: 10px;
  font-weight: 300;}
.te-block .btn {display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 14px 28px;
  border-radius: 6px;
  text-decoration: none;
  font-family: 'Inter', sans-serif;
  font-size: 0.85rem;
  font-weight: 600;
  letter-spacing: 0.6px;
  text-transform: uppercase;
  transition: all 0.22s ease;
  border: 2px solid transparent;
  cursor: pointer;
  white-space: nowrap;}
.te-block .btn-primary {background: var(--teal);
  color: white;
  border-color: var(--teal);
  box-shadow: 0 4px 14px rgba(26,110,98,0.3);}
.te-block .btn-primary:hover {background: var(--teal-light);
  border-color: var(--teal-light);
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(26,110,98,0.4);}
.te-block .btn-outline {background: transparent;
  color: white;
  border-color: rgba(255,255,255,0.6);
  backdrop-filter: blur(4px);}
.te-block .btn-outline:hover {background: white;
  color: var(--navy);
  border-color: white;
  transform: translateY(-2px);}
.te-block .btn-outline-navy {background: transparent;
  color: var(--navy);
  border-color: var(--navy);}
.te-block .btn-outline-navy:hover {background: var(--navy); color: white; transform: translateY(-2px);}
.te-block .btn-gold {background: var(--gold);
  color: white;
  border-color: var(--gold);
  box-shadow: 0 4px 14px rgba(184,133,42,0.3);}
.te-block .btn-gold:hover {background: #a67520;
  border-color: #a67520;
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(184,133,42,0.4);}
.te-block .btn-white {background: white;
  color: var(--navy);
  border-color: white;
  box-shadow: 0 4px 14px rgba(0,0,0,0.15);}
.te-block .btn-white:hover {background: var(--cream); transform: translateY(-2px);}
.te-block .btn-sm {padding: 9px 18px; font-size: 0.78rem;}
.te-block .btn-lg {padding: 16px 36px; font-size: 0.9rem;}
.te-block section {padding: 80px 24px;}
.te-block .section-inner {max-width: 1280px; margin: 0 auto;}
.te-block .section-eyebrow {display: inline-block;
  font-family: 'Inter', sans-serif;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 3px;
  text-transform: uppercase;
  color: var(--teal);
  margin-bottom: 12px;}
.te-block .section-title {font-size: clamp(1.7rem, 3.5vw, 2.6rem);
  color: var(--navy);
  margin-bottom: 20px;
  line-height: 1.2;
  font-weight: 700;}
.te-block .section-title em {font-style: italic; color: var(--teal);}
.te-block .section-lead {font-size: 1.08rem;
  color: var(--text-mid);
  max-width: 640px;
  margin-bottom: 48px;
  line-height: 1.8;
  font-weight: 300;}
.te-block .bg-cream {background: var(--cream);}
.te-block .bg-navy {background: var(--navy);}
.te-block .bg-teal {background: var(--teal);}
.te-block .text-white {color: white !important;}
.te-block .title-line {width: 48px; height: 3px;
  background: var(--teal);
  border-radius: 2px;
  margin: 16px 0 24px;}
.te-block .title-line-gold {background: var(--gold);}
.te-block .stats-bar {background: var(--navy);
  padding: 0;
  border-top: 1px solid rgba(255,255,255,0.06);}
.te-block .stats-inner {max-width: 1280px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(4, 1fr);}
.te-block .stat-item {padding: 44px 24px;
  text-align: center;
  border-right: 1px solid rgba(255,255,255,0.06);
  position: relative;}
.te-block .stat-item:last-child {border-right: none;}
.te-block .stat-item::after {content: '';
  position: absolute;
  bottom: 0; left: 50%;
  transform: translateX(-50%);
  width: 0; height: 3px;
  background: var(--teal);
  transition: width 0.4s ease;
  border-radius: 2px;}
.te-block .stat-item:hover::after {width: 60%;}
.te-block .stat-number {font-family: 'Playfair Display', serif;
  font-size: 3rem;
  font-weight: 700;
  color: var(--gold-light);
  line-height: 1;
  margin-bottom: 8px;}
.te-block .stat-label {font-family: 'Inter', sans-serif;
  font-size: 0.72rem;
  color: rgba(255,255,255,0.55);
  text-transform: uppercase;
  letter-spacing: 1.5px;
  font-weight: 500;}
.te-block .about-grid {display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 24px;
  margin-top: 8px;}
.te-block .about-card {background: white;
  border-radius: var(--radius-lg);
  padding: 36px 28px;
  box-shadow: var(--shadow-md);
  border: 1px solid var(--border);
  transition: transform 0.25s, box-shadow 0.25s;
  position: relative;
  overflow: hidden;}
.te-block .about-card::before {content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 4px;
  background: linear-gradient(90deg, var(--teal), var(--teal-light));
  border-radius: var(--radius-lg) var(--radius-lg) 0 0;}
.te-block .about-card:hover {transform: translateY(-5px);
  box-shadow: var(--shadow-lg);}
.te-block .about-card-icon {width: 52px; height: 52px;
  background: var(--teal-pale);
  border-radius: 12px;
  display: flex; align-items: center; justify-content: center;
  font-size: 1.5rem;
  margin-bottom: 20px;}
.te-block .about-card h3 {font-size: 1.1rem;
  color: var(--navy);
  margin-bottom: 12px;
  font-weight: 600;}
.te-block .about-card p {font-size: 0.9rem;
  color: var(--text-light);
  line-height: 1.7;}
.te-block .features-list {display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin-top: 24px;}
.te-block .feature-item {display: flex; align-items: center; gap: 10px;
  font-size: 0.88rem;
  color: var(--text-mid);}
.te-block .feature-check {width: 20px; height: 20px;
  background: var(--teal-pale);
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  color: var(--teal);
  font-size: 0.7rem;
  flex-shrink: 0;}
.te-block .trip-card {background: white;
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-md);
  border: 1px solid var(--border);
  transition: transform 0.25s, box-shadow 0.25s;}
.te-block .trip-card:hover {transform: translateY(-5px);
  box-shadow: var(--shadow-lg);}
.te-block .trip-card-header {padding: 28px 28px 24px;
  color: white;
  position: relative;
  overflow: hidden;}
.te-block .trip-card-header::before {content: '';
  position: absolute;
  top: -30px; right: -30px;
  width: 120px; height: 120px;
  border-radius: 50%;
  background: rgba(255,255,255,0.07);}
.te-block .trip-card-header::after {content: '';
  position: absolute;
  bottom: -20px; right: 20px;
  width: 80px; height: 80px;
  border-radius: 50%;
  background: rgba(255,255,255,0.05);}
.te-block .trip-card-header .badge {display: inline-block;
  font-size: 0.65rem;
  font-weight: 600;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  padding: 3px 10px;
  border-radius: 50px;
  background: rgba(255,255,255,0.15);
  margin-bottom: 12px;}
.te-block .trip-card-header h3 {font-size: 1.4rem;
  margin-bottom: 4px;
  position: relative;}
.te-block .trip-card-header .price {font-family: 'Playfair Display', serif;
  font-size: 2.2rem;
  font-weight: 700;
  color: var(--gold-light);
  line-height: 1;
  margin-top: 10px;
  position: relative;}
.te-block .trip-card-header .price-label {font-size: 0.75rem;
  color: rgba(255,255,255,0.6);
  font-family: 'Inter', sans-serif;
  font-weight: 400;}
.te-block .trip-card-body {padding: 24px 28px;}
.te-block .trip-card-body p {font-size: 0.9rem;
  color: var(--text-light);
  margin-bottom: 18px;
  line-height: 1.7;}
.te-block .trip-meta {display: flex; flex-direction: column; gap: 8px;
  margin-bottom: 20px;}
.te-block .trip-meta-item {display: flex; align-items: center; gap: 10px;
  font-size: 0.85rem;
  color: var(--text-mid);}
.te-block .trip-meta-icon {width: 28px; height: 28px;
  background: var(--teal-pale);
  border-radius: 6px;
  display: flex; align-items: center; justify-content: center;
  font-size: 0.8rem;
  flex-shrink: 0;
  color: var(--teal);}
.te-block .lunch-options-table {width: 100%;
  border-collapse: collapse;
  font-size: 0.82rem;
  margin: 12px 0 16px;
  border-radius: 8px;
  overflow: hidden;
  border: 1px solid var(--border);}
.te-block .lunch-options-table th {background: var(--navy);
  color: rgba(255,255,255,0.9);
  padding: 8px 12px;
  text-align: left;
  font-weight: 600;
  font-size: 0.75rem;
  letter-spacing: 0.5px;
  text-transform: uppercase;}
.te-block .lunch-options-table td {padding: 8px 12px;
  border-bottom: 1px solid var(--border);
  color: var(--text-mid);}
.te-block .lunch-options-table tr:last-child td {border-bottom: none;}
.te-block .lunch-options-table tr:nth-child(even) td {background: var(--cream);}
.te-block .trip-note {background: #fffbeb;
  border: 1px solid #f0c060;
  border-radius: 8px;
  padding: 10px 14px;
  font-size: 0.82rem;
  color: #7c5c00;
  margin-top: 10px;}
.te-block .accordion {margin-top: 32px; display: flex; flex-direction: column; gap: 10px;}
.te-block .accordion-item {background: white;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: var(--shadow-sm);}
.te-block .accordion-header {width: 100%;
  background: white;
  border: none;
  text-align: left;
  padding: 20px 24px;
  font-family: 'Playfair Display', serif;
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--navy);
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  transition: background 0.2s, color 0.2s;}
.te-block .accordion-header:hover {background: var(--cream);}
.te-block .accordion-header.open {background: var(--navy);
  color: white;}
.te-block .accordion-icon {width: 26px; height: 26px;
  border-radius: 50%;
  background: var(--teal-pale);
  color: var(--teal);
  display: flex; align-items: center; justify-content: center;
  font-size: 1rem;
  font-weight: 300;
  flex-shrink: 0;
  transition: transform 0.3s, background 0.2s;}
.te-block .accordion-header.open .accordion-icon {transform: rotate(45deg);
  background: rgba(255,255,255,0.15);
  color: white;}
.te-block .accordion-body {display: none;
  padding: 24px 28px;
  background: var(--cream);
  font-size: 0.92rem;
  line-height: 1.8;
  color: var(--text-mid);
  border-top: 1px solid rgba(0,0,0,0.06);}
.te-block .accordion-body.open {display: block;}
.te-block .accordion-body h4 {color: var(--navy);
  font-size: 0.9rem;
  margin: 16px 0 6px;
  font-weight: 600;
  letter-spacing: 0.3px;}
.te-block .accordion-body ul {padding-left: 20px; margin: 8px 0;}
.te-block .accordion-body li {margin-bottom: 6px;}
.te-block .accordion-body p + p {margin-top: 10px;}
.te-block .calendar-wrapper {background: white;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-md);
  border: 1px solid var(--border);
  overflow: hidden;}
.te-block .calendar-header {background: var(--navy);
  color: white;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 20px;}
.te-block .calendar-header h3 {font-size: 1rem;
  font-weight: 600;
  font-family: 'Inter', sans-serif;
  letter-spacing: 0.3px;}
.te-block .cal-nav-btn {background: rgba(255,255,255,0.1);
  border: 1px solid rgba(255,255,255,0.2);
  color: white;
  width: 30px; height: 30px;
  border-radius: 50%;
  cursor: pointer;
  font-size: 1rem;
  display: flex; align-items: center; justify-content: center;
  transition: background 0.2s;}
.te-block .cal-nav-btn:hover {background: rgba(255,255,255,0.2);}
.te-block .calendar-grid {padding: 16px;}
.te-block .calendar-weekdays {display: grid;
  grid-template-columns: repeat(7, 1fr);
  text-align: center;
  font-size: 0.7rem;
  font-weight: 700;
  color: var(--text-light);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 8px;}
.te-block .calendar-days {display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 3px;}
.te-block .cal-day {aspect-ratio: 1;
  display: flex; align-items: center; justify-content: center;
  border-radius: 8px;
  font-size: 0.82rem;
  cursor: pointer;
  transition: all 0.15s;
  border: none;
  background: none;
  color: var(--text);
  font-family: 'Inter', sans-serif;
  font-weight: 500;}
.te-block .cal-day:hover:not(.unavailable):not(.other-month) {background: var(--cream);}
.te-block .cal-day.other-month {color: #d0d8e4; pointer-events: none;}
.te-block .cal-day.today {font-weight: 700; border: 2px solid var(--navy);}
.te-block .cal-day.available {background: #d1f5ee; color: #0a5e50; font-weight: 600;}
.te-block .cal-day.available:hover {background: #b3eddf;}
.te-block .cal-day.provisional {background: #fff3cd; color: #7c5c00; font-weight: 600;}
.te-block .cal-day.provisional:hover {background: #ffe69c;}
.te-block .cal-day.booked {background: #fde8e8; color: #8b1a1a; cursor: not-allowed;}
.te-block .calendar-legend {display: flex; gap: 14px;
