.te-block .legend-dot.available {background: #d1f5ee; border: 1px solid #0a5e50;}
.te-block .legend-dot.provisional {background: #fff3cd; border: 1px solid #7c5c00;}
.te-block .legend-dot.booked {background: #fde8e8; border: 1px solid #8b1a1a;}
.te-block .booking-layout {display: grid;
  grid-template-columns: 1fr 380px;
  gap: 40px;
  align-items: start;}
.te-block .form-card {background: white;
