  display: flex; align-items: center; justify-content: center;
  font-size: 0.72rem; flex-shrink: 0;}
.te-block .trip-row .form-row {grid-template-columns: 1fr 1fr 1fr;}
.te-block .checkbox-group {display: flex; align-items: flex-start; gap: 12px;
  margin-bottom: 14px;
  font-size: 0.86rem;
  color: var(--text-mid);
