  flex-shrink: 0; box-shadow: 0 2px 8px rgba(26,110,98,0.3);}
.te-block .step-text {font-size: 0.87rem; color: var(--text-mid); line-height: 1.6; padding-top: 4px;}
.te-block .step-text strong {color: var(--navy);}
.te-block .panel-card {background: white;
