.te-block .text-center {text-align: center;}
.te-block .mt-0 {margin-top: 0 !important;}
.te-block .mt-24 {margin-top: 24px;}
.te-block .mt-32 {margin-top: 32px;}
.te-block .mb-24 {margin-bottom: 24px;}
.te-block .mb-32 {margin-bottom: 32px;}
.te-block hr.divider {border: none;
  border-top: 1px solid var(--border);
  margin: 20px 0;}
@media (max-width: 1024px) {
.te-block .booking-layout {grid-template-columns: 1fr;}
.te-block .contact-grid {grid-template-columns: 1fr;}
.te-block .footer-grid {grid-template-columns: 1fr 1fr; padding: 40px 24px;}
.te-block .footer-cta-strip {padding: 24px;}
.te-block .footer-bottom {padding: 20px 24px;}
.te-block .booking-side-panel {position: static;}
.te-block .trips-page-layout {grid-template-columns: 1fr !important;}
.te-block .stats-inner {grid-template-columns: repeat(2, 1fr);}
.te-block .stat-item {border-right: none; border-bottom: 1px solid rgba(255,255,255,0.06);}
.te-block .stat-item:nth-child(odd) {border-right: 1px solid rgba(255,255,255,0.06);}
}
@media (max-width: 900px) {
.te-block .nav-links {display: none; flex-direction: column;}
.te-block .nav-links.open {display: flex; position: absolute;
    top: 100%; left: 0; right: 0;
    background: var(--navy);
    padding: 8px 16px 16px;
    box-shadow: 0 12px 24px rgba(0,0,0,0.4);
    z-index: 999;}
.te-block .nav-links.open li a {padding: 12px 8px; border-radius: 0; border-bottom: 1px solid rgba(255,255,255,0.05);}
.te-block .nav-links.open li:last-child a {border-bottom: none;}
.te-block .nav-hamburger {display: flex;}
.te-block nav {position: relative;}
.te-block .nav-inner {flex-wrap: wrap; height: auto; padding: 12px 20px;}
.te-block .form-row {grid-template-columns: 1fr;}
.te-block .trip-row .form-row {grid-template-columns: 1fr 1fr;}
.te-block .page-hero-content {padding: 28px 24px;}
.te-block .page-hero {min-height: 420px;}
.te-block .hero {min-height: 500px;}
.te-block .hero-content {text-align: center; padding: 90px 24px 70px;}
.te-block .hero-actions {justify-content: center;}
.te-block .support-appeal {padding: 36px 24px;}
}
@media (max-width: 640px) {
.te-block section {padding: 56px 16px;}
.te-block .hero {min-height: 420px;}
.te-block .hero-content {padding: 80px 16px 60px;}
.te-block .page-hero {min-height: 320px;}
.te-block .page-hero-content {padding: 24px 20px;}
.te-block .form-card {padding: 24px 20px;}
.te-block .footer-grid {grid-template-columns: 1fr; padding: 32px 20px;}
.te-block .footer-bottom {flex-direction: column; text-align: center; padding: 16px 20px;}
.te-block .footer-cta-strip {padding: 20px; flex-direction: column; text-align: center;}
.te-block .trip-row .form-row {grid-template-columns: 1fr;}
.te-block .stats-inner {grid-template-columns: 1fr 1fr;}
.te-block .features-list {grid-template-columns: 1fr;}
}
.te-block .two-col {display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 64px;
      align-items: center;}
.te-block .two-col.reverse {direction: rtl;}
.te-block .two-col.reverse > * {direction: ltr;}
.te-block .img-frame {position: relative;
      border-radius: var(--radius-lg);
      overflow: hidden;
      box-shadow: var(--shadow-lg);}
.te-block .img-frame img {width: 100%; display: block;}
.te-block .img-frame-badge {position: absolute;
      bottom: -16px; right: -16px;
      background: var(--navy);
      color: white;
      border-radius: 12px;
      padding: 18px 22px;
      text-align: center;
      box-shadow: var(--shadow-lg);}
.te-block .img-frame-badge .num {font-family: 'Playfair Display', serif;
      font-size: 2.2rem;
      font-weight: 700;
      color: var(--gold-light);
      line-height: 1;}
.te-block .img-frame-badge .lbl {font-size: 0.72rem;
      color: rgba(255,255,255,0.65);
      text-transform: uppercase;
      letter-spacing: 1px;
      white-space: nowrap;}
.te-block .trips-grid-home {display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
      margin-top: 40px;}
.te-block .trip-summary-card {background: white;
      border-radius: var(--radius-lg);
      overflow: hidden;
      box-shadow: var(--shadow-md);
      border: 1px solid var(--border);
      transition: transform 0.25s, box-shadow 0.25s;
      display: flex;
      flex-direction: column;}
.te-block .trip-summary-card:hover {transform: translateY(-5px);
      box-shadow: var(--shadow-lg);}
.te-block .trip-summary-top {padding: 24px 24px 20px;
      color: white;
      position: relative;
      overflow: hidden;}
.te-block .trip-summary-top::before {content: '';
      position: absolute;
      top: -30px; right: -30px;
      width: 110px; height: 110px;
      border-radius: 50%;
      background: rgba(255,255,255,0.07);}
.te-block .trip-summary-top .trip-icon {font-size: 1.8rem; margin-bottom: 10px;}
.te-block .trip-summary-top h3 {font-size: 1.2rem; margin-bottom: 4px;}
.te-block .trip-summary-top .hours {font-size: 0.82rem; color: rgba(255,255,255,0.7);}
.te-block .trip-summary-bottom {padding: 20px 24px;
      flex: 1;
      display: flex;
      flex-direction: column;
      justify-content: space-between;}
.te-block .trip-summary-bottom p {font-size: 0.88rem;
      color: var(--text-light);
      line-height: 1.6;
      margin-bottom: 16px;}
.te-block .trip-price-row {display: flex;
      justify-content: space-between;
      align-items: center;
      border-top: 1px solid var(--border);
      padding-top: 14px;}
.te-block .trip-price-row .price {font-family: 'Playfair Display', serif;
      font-size: 1.6rem;
      font-weight: 700;
      color: var(--gold);}
.te-block .charity-strip {background: var(--cream);
      padding: 28px 32px;
      border-radius: var(--radius-lg);
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 20px;
      border: 1px solid var(--border);
      margin-top: 48px;
      flex-wrap: wrap;}
.te-block .charity-strip p {font-family: 'Playfair Display', serif;
      font-style: italic;
      font-size: 1.05rem;
      color: var(--text-mid);
      max-width: 580px;}
@media (max-width: 900px) {
.te-block .two-col {grid-template-columns: 1fr; gap: 32px;}
.te-block .trips-grid-home {grid-template-columns: 1fr;}
.te-block .charity-strip {flex-direction: column; text-align: center;}
}
.te-block .trips-page-layout {display: grid;
      grid-template-columns: 1fr 380px;
      gap: 48px;
      align-items: start;}
.te-block .booking-side-panel {position: sticky; top: 88px;}
@media (max-width: 960px) {
.te-block .trips-page-layout {grid-template-columns: 1fr;}
.te-block .booking-side-panel {position: static;}
}
.te-block .how-to-book-steps {margin-top: 20px;}
.te-block .step {display: flex;
      gap: 16px;
      margin-bottom: 20px;}
.te-block .step-num {width: 32px;
      height: 32px;
      background: var(--teal);
      color: white;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-family: sans-serif;
      font-size: 0.85rem;
      font-weight: bold;
      flex-shrink: 0;}
.te-block .step-text {font-family: sans-serif; font-size: 0.88rem; color: var(--text-light); line-height: 1.6;}
.te-block .step-text strong {color: var(--navy);}
.te-block .location-map-placeholder {background: #e8f0f7;
      border-radius: 8px;
      height: 220px;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      color: var(--navy);
      font-family: sans-serif;
      text-align: center;
      gap: 8px;
      border: 1px solid var(--border);
      margin-top: 16px;}
.te-block .support-grid {display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
      margin-top: 40px;}
.te-block .support-card-new {background: white;
      border-radius: 14px;
      padding: 32px 28px;
      box-shadow: 0 4px 16px rgba(13,33,55,0.08);
      border: 1px solid #e2e8f0;
      border-top: 4px solid #b8852a;
      display: flex;
      flex-direction: column;}
.te-block .support-card-new .icon {font-size: 2rem;
      margin-bottom: 16px;}
.te-block .support-card-new h3 {font-family: 'Playfair Display', serif;
      font-size: 1.1rem;
      color: #0d2137;
      margin-bottom: 10px;}
.te-block .support-card-new p {font-size: 0.88rem;
      color: #6b7a8d;
      line-height: 1.7;
      flex: 1;}
.te-block .support-card-new .card-footer {margin-top: 20px;}
.te-block .bank-table {width: 100%;
      border-collapse: collapse;
      margin-top: 16px;
      font-size: 0.83rem;}
.te-block .bank-table tr {border-bottom: 1px solid #e2e8f0;}
.te-block .bank-table td {padding: 8px 4px;
      color: #3d4a5c;}
.te-block .bank-table td:first-child {color: #6b7a8d;
      font-weight: 500;
      width: 44%;}
.te-block .bank-table td:last-child {font-weight: 600;
      color: #0d2137;}
.te-block .contact-box {background: #f9f6f1;
      border-radius: 8px;
      padding: 14px 16px;
      margin-top: 16px;
      font-size: 0.85rem;
      color: #3d4a5c;
      line-height: 1.8;}
.te-block .contact-box a {color: #1a6e62; text-decoration: none;}
.te-block .contact-box a:hover {text-decoration: underline;}
.te-block .teal-border {border-top-color: #1a6e62 !important;}
@media (max-width: 900px) {
.te-block .support-grid {grid-template-columns: repeat(2, 1fr);}
}
@media (max-width: 560px) {
.te-block .support-grid {grid-template-columns: 1fr;}
}
:root {--shadow: var(--shadow-md);}
.te-block /* styles that were referenced but missing on the static site */
.section-label {display:block; font-family:'Inter',sans-serif; font-size:0.7rem; font-weight:700; letter-spacing:3px; text-transform:uppercase; color:var(--teal); margin-bottom:12px;}
.te-block .trip-detail {display:flex; align-items:center; gap:8px; font-size:0.88rem; color:var(--text-mid); margin-bottom:6px;}
.te-block .trip-detail-icon {width:26px; height:26px; background:var(--teal-pale); border-radius:6px; display:inline-flex; align-items:center; justify-content:center; font-size:0.8rem; flex-shrink:0;}
.te-block .support-hero-box {background:linear-gradient(135deg, var(--navy) 0%, #1a3a5c 60%, #0d3348 100%); border-radius:var(--radius-lg); padding:56px 48px; color:white; text-align:center;}
.te-block .support-hero-box h2 {font-size:2.2rem; color:white; margin-bottom:16px;}
.te-block .support-hero-box p {color:rgba(255,255,255,0.82); max-width:720px; margin:0 auto 14px; line-height:1.8;}
.te-block .support-hero-box > div {max-width:560px; margin-left:auto; margin-right:auto;}
.te-block .progress-bar-wrap {height:12px; background:rgba(255,255,255,0.12); border-radius:50px; overflow:hidden;}
.te-block .progress-label {font-size:0.82rem; color:rgba(255,255,255,0.6) !important; margin-top:8px !important;}
.te-block .title-line {font-size:0; line-height:0;}
@media (max-width: 900px) {
.te-block .support-hero-box {padding:36px 24px;}
}

/* ===== override WordPress theme defaults the static site relied on ===== */
.te-block h1, .te-block h2, .te-block h3, .te-block h4, .te-block h5, .te-block h6 { font-weight:700; }
.te-block h1 { font-size:2em; } .te-block h2 { font-size:1.5em; } .te-block h3 { font-size:1.17em; } .te-block h4 { font-size:1em; }
.te-block a { color:var(--teal); background:transparent; }
.te-block label { display:inline; line-height:inherit; vertical-align:baseline; }
.te-block .checkbox-group label { line-height:1.55; }
.te-block button { font-family:inherit; line-height:normal; white-space:normal; }
.te-block table td, .te-block table th { border:0; line-height:inherit; vertical-align:middle; }
.te-block table tbody > tr > td, .te-block table tbody tr:hover > td { background-color:transparent; }
.te-block img { height:auto; }

/* ===== Elementor page structure ===== */
.e-con.te-block { --padding-top:0px; --padding-right:0px; --padding-bottom:0px; --padding-left:0px; --gap:0px 0px; --row-gap:0px; --column-gap:0px; padding:0; gap:0; }
.e-con.te-header { position:sticky; top:0; z-index:1000; }
.admin-bar .e-con.te-header { top:32px; }
@media (max-width: 900px) { .e-con.te-header { position:relative; top:0; } }
body .te-block .elementor-widget-text-editor, body .te-block .elementor-widget-html { color:inherit; font-family:inherit; font-size:inherit; font-weight:inherit; line-height:inherit; }
body.elementor-template-canvas { background: var(--off-white); }
